package fr.gemsofrod.encyclopedie.data

/** Nederlandse vertalingen van de naam en de beschrijvende teksten van de edelstenen. */
object GemTranslationsNl {
    val data: Map<String, GemTranslation> = mapOf(
        "grenat-pyrope" to GemTranslation(
            nom = "Pyroopgranaat",
            descriptionCourte = "De klassieke bloedrode granaat, zonder rhodoliet-verdunning.",
            descriptionLongue = "Pyroop is de meest intens rode granaat van de pyralspietgroep; zijn kleur is te danken aan magnesium en vaak een vleugje chroom. Het is van oudsher de granaat van Bohemen, in de 17e-19e eeuw in grote hoeveelheden geslepen tot kleine steentjes die in pavézetting werden gevat.",
            particularites = "In tegenstelling tot rhodoliet bevat zuivere pyroop geen ijzer in significante hoeveelheden.",
            inclusions = "Kristallen van bijkomende mineralen (vaak apatiet), interne breuken en incidentele spanningsvelden; over het algemeen een vrij zuivere steen.",
            lithotherapie = "Een steen van vitaliteit en moed; pyroopgranaat zou de fysieke energie stimuleren en de motivatie doen herleven in tijden van vermoeidheid of ontmoediging."
        ),
        "eudialyte" to GemTranslation(
            nom = "Eudialiet",
            descriptionCourte = "Frambooskleurige vlekken in een grijze matrix, bijgenaamd de \"dronkenmansteen\".",
            descriptionLongue = "Eudialiet vormt frambooskleurige tot roze vlekken en aders in een grijs alkalisch gesteente (vaak geassocieerd met nefelien), wat het in Rusland de bijnaam \"dronkenmansteen\" opleverde. Zelden puur geslepen als facetsteen, wordt hij vooral gebruikt als cabochon of trommelsteen.",
            particularites = "Bijna altijd verkocht als cabochon of ruw gepolijste steen, zelden geslepen wegens zijn gedeeltelijke ondoorzichtigheid.",
            lithotherapie = "Bijgenaamd de steen van zelfliefde, wordt eudialiet gebruikt om emotionele wonden te verzachten en zelfacceptatie te bevorderen."
        ),
        "andesine" to GemTranslation(
            nom = "Andesien",
            descriptionCourte = "Een veldspaat die naargelang de vindplaats van rood tot groen varieert, in het hart van een behandelingscontroverse.",
            descriptionLongue = "Natuurlijke rode andesien uit Congo en Oregon bestaat wel degelijk in de natuur, maar een groot deel van de markt uit de jaren 2000 was in werkelijkheid afkomstig van Chinese labradoriet die met koper was gediffundeerd om deze tint na te bootsen — een episode die in de gemmologie berucht is gebleven. Er bestaat ook een zeldzamere groene variëteit.",
            particularites = "Een laboratoriumcertificaat met de vermelding \"onbehandeld\" is onmisbaar voor rode stenen van deze soort.",
            inclusions = "Inclusies van natief koper als fijne plaatjes, verantwoordelijk voor roodachtige glinsteringen bij bepaalde vindplaatsen (de zogenaamde \"rode\" andesien).",
            lithotherapie = "Geassocieerd met levensvreugde en vitaliteit, zou andesien energie teruggeven tijdens periodes van emotionele vermoeidheid."
        ),
        "rubis" to GemTranslation(
            nom = "Robijn",
            descriptionCourte = "Rode korund, de koninklijke edelsteen bij uitstek.",
            descriptionLongue = "Robijn is de rode variëteit van korund, waarvan de kleur afkomstig is van sporen chroom. Als symbool van passie en macht sinds de oudheid is hij een van de vier historische edelstenen naast diamant, smaragd en saffier. De mooiste stenen vertonen een zeer intens \"duivenbloed\"-rood.",
            particularites = "Rode fluorescentie onder UV; rutielinsluitsels (\"zijde\") die asterisme kunnen veroorzaken (een zesstralige ster).",
            inclusions = "Rutielinsluitsels als fijne zijdeachtige naaldjes (\"zijde\"), soms gerangschikt langs de drie assen van het kristal tot asterisme; zirkoonkristallen omgeven door een spanningshalo, helende \"vingerafdruk\"-insluitsels en veelvoorkomende polysynthetische tweelingvorming, vooral bij onbehandelde Birmese stenen.",
            lithotherapie = "De steen van passie en vitaliteit bij uitstek; robijn wordt van oudsher geassocieerd met moed, zelfvertrouwen en bescherming tegen negatieve energieën."
        ),
        "grenat-almandin" to GemTranslation(
            nom = "Almandijn-/pyroopgranaat",
            descriptionCourte = "Dieprode granaat, nooit behandeld.",
            descriptionLongue = "Deze twee soorten uit de granaatgroep vormen een continue reeks en worden vaak samen verhandeld. Hun intense rood, bij almandijn soms bruinachtig, maakt er toegankelijke stenen van die al sinds de Romeinse tijd zeer gewaardeerd worden in de juwelierskunst.",
            particularites = "Geen splijting, hoge lichtbreking, nooit thermisch of chemisch behandeld.",
            inclusions = "Kristallen van apatiet, rutiel of zirkoon, soms georiënteerd voor een licht zijdeachtig effect; vezelige insluitsels kunnen een vier- of zesstralig asterisme veroorzaken.",
            lithotherapie = "Een steen van geaardheid en innerlijke kracht; almandijngranaat zou helpen om moeilijke periodes met vastberadenheid door te komen."
        ),
        "spinelle-rouge" to GemTranslation(
            nom = "Rode spinel",
            descriptionCourte = "Lange tijd verward met robijn.",
            descriptionLongue = "Eeuwenlang werd rode spinel voor robijn aangezien: de beroemde \"Black Prince's Ruby\" gezet in de Britse rijkskroon is in werkelijkheid een spinel. In de overgrote meerderheid van de gevallen van nature onbehandeld, herwint hij tegenwoordig de erkenning die hem toekomt bij verzamelaars.",
            particularites = "Kristallen zijn vaak octaëdrisch; bijna altijd onbehandeld.",
            inclusions = "Kleine octaëdrische kristallen (spinel-in-spinel), wolken van fijne deeltjes en incidentele groeizonering; van nature een onbehandelde steen.",
            lithotherapie = "Geassocieerd met vernieuwing en vitaliteit, wordt rode spinel gebruikt om energie te stimuleren en aan te moedigen weer op te staan na tegenslag."
        ),
        "tourmaline-rubellite" to GemTranslation(
            nom = "Rubelliet toermalijn",
            descriptionCourte = "Intens rood door mangaan.",
            descriptionLongue = "Rubelliet is de rode tot frambooskleurige roze variëteit van de toermalijngroep, een boor-aluminiumsilicaat met het breedste kleurenpalet van het minerale rijk. Zijn sterke pleochroïsme doet de intensiteit variëren naargelang de kijkhoek.",
            particularites = "Uitgesproken pleochroïsme; karakteristieke gestreepte prismatische kristallen.",
            inclusions = "Vloeistofinsluitsels versplinterd tot fijne \"katoendraden\" (trichieten) en holle buisjes evenwijdig aan de kristalas, vaak voorkomend bij Braziliaanse of Afrikaanse stenen.",
            lithotherapie = "Rubelliet zou het hart openen voor liefde en vreugde, en oude emotionele wonden verzachten."
        ),
        "grenat-rhodolite" to GemTranslation(
            nom = "Rhodolietgranaat",
            descriptionCourte = "\"Framboos\"-achtig paarsrood.",
            descriptionLongue = "Een tussenmengsel van pyroop en almandijn, rhodoliet biedt een stralende paarsrode tint, lichter dan de klassieke almandijn. Zijn naam komt van het Griekse \"rhodon\" (roos), verwijzend naar zijn kleur.",
            particularites = "Uitstekende transparantie, nooit behandeld.",
            inclusions = "Bijkomende kristallen (apatiet, zirkoon) en fijne interne vezeltjes; over het algemeen zuiver met het blote oog.",
            lithotherapie = "Een steen van emotioneel evenwicht; rhodoliet zou woede-uitbarstingen temperen en tegelijk passie en enthousiasme behouden."
        ),
        "painite" to GemTranslation(
            nom = "Painiet",
            descriptionCourte = "Lange tijd beschouwd als het zeldzaamste edelsteenmineraal ter wereld.",
            descriptionLongue = "Ontdekt in 1951 door de Britse gemmoloog Arthur Pain, was painiet bijna vijftig jaar lang slechts bekend van twee of drie kristallen, tot in de jaren 2000 nieuwe vindplaatsen in Myanmar werden ontdekt. Zijn roodbruine tot oranje tint en hoge hardheid maken er een uiterst gegeerde verzamelaarssteen van.",
            particularites = "Slechts één bekende vindplaats ter wereld; geslepen stenen zijn bijna allemaal kleiner dan 2 karaat.",
            inclusions = "Een uiterst zeldzame soort; interne insluitsels zijn nog weinig gedocumenteerd, aangezien de meeste bekende stenen zeer klein zijn.",
            lithotherapie = "Een zeldzaam mineraal; painiet wordt in de lithotherapie geassocieerd met doorzettingsvermogen en vertrouwen in de eigen weg, ook buiten de gebaande paden."
        ),
        "bixbite" to GemTranslation(
            nom = "Bixbiet",
            descriptionCourte = "Rode beryl, een van de zeldzaamste edelstenen ter wereld.",
            descriptionLongue = "Lang bekend als \"bixbiet\" — een naam die gemmologische laboratoria tegenwoordig afraden omdat hij verward kan worden met bixbyiet, een niet-verwant mineraal — dankt rode beryl zijn intense kleur aan mangaan. Hij komt vrijwel uit één enkele vindplaats ter wereld, in de Wah Wah Mountains in Utah, waar kristallen die na slijpen meer dan één karaat opleveren uitzonderlijk blijven.",
            particularites = "Geslepen kristallen zijn bijna altijd kleiner dan één karaat; een vrijwel unieke bron wereldwijd, wat er een van de zeldzaamste en duurste edelstenen per karaat van maakt.",
            inclusions = "Uiterst zeldzaam en over het algemeen klein; kan verlengingsbuisjes en zeldzame bijkomende kristallen vertonen, zoals andere berylen.",
            lithotherapie = "Bixbiet wordt geassocieerd met vitaliteit en passie, een steen die creatieve energie en zelfvertrouwen zou stimuleren."
        ),
        "crocoite" to GemTranslation(
            nom = "Crocoïet",
            descriptionCourte = "Levendige oranjerode prismatische kristallen, een schat voor verzamelaars.",
            descriptionLongue = "Crocoïet vormt langwerpige prismatische kristallen in een elektrisch oranjerood, tot de meest spectaculaire van het minerale rijk. Uiterst broos en zacht, wordt het vrijwel uitsluitend als mineraalspecimen verzameld in plaats van geslepen.",
            particularites = "Te zacht en te splijtbaar voor dagelijks juwelengebruik; vrijwel uitsluitend een verzamelaarssteen.",
            inclusions = "Vaak brosse prismatische kristallen, zelden geslepen; interne insluitsels blijven weinig gedocumenteerd omdat geslepen stenen zo schaars zijn.",
            lithotherapie = "Een steen van energie en creativiteit; crocoïet zou passie en enthousiasme voor nieuwe projecten stimuleren."
        ),
        "grenat-malaya" to GemTranslation(
            nom = "Malayagranaat",
            descriptionCourte = "Een warm roze-oranje geboren uit de vermenging van twee granaten.",
            descriptionLongue = "Malayagranaat (\"verstotene\" in het Swahili, omdat mijnwerkers hem lange tijd als van onzuivere samenstelling beschouwden) is een natuurlijke mengeling van pyroop en spessartiet met unieke oranje tot zalmroze tinten, zonder behandeling.",
            particularites = "Geen enkele behandeling is nodig of gebruikelijk; 100% natuurlijke kleur.",
            inclusions = "Incidentele bijkomende kristallen en fijne interne vezeltjes, vergelijkbaar met andere granaten uit de pyroop-spessartietreeks.",
            lithotherapie = "Geassocieerd met levensvreugde, wordt malayagranaat gebruikt om creativiteit te stimuleren en somberheid te verdrijven."
        ),
        "zircon-hyacinthe" to GemTranslation(
            nom = "Hyacint zirkoon",
            descriptionCourte = "De historische roodbruine variëteit die zirkoon zijn oude naam gaf.",
            descriptionLongue = "Genoemd naar de bloem, is hyacint de oranje tot roodbruine variëteit van zirkoon, sinds de oudheid bekend en geslepen. Zijn hoge brekingsindex geeft hem bij gelijke grootte een schittering die vergelijkbaar is met die van diamant.",
            particularites = "Hoge dubbele breking die met het blote oog een zichtbare verdubbeling van de facetranden van de tafel veroorzaakt.",
            inclusions = "Uitgesproken dubbele breking die een duidelijke verdubbeling van de interne facetranden veroorzaakt; metamicte zones en spanningsbreuken komen vaak voor.",
            lithotherapie = "Hyacint zirkoon wordt van oudsher geassocieerd met succes en zelfvertrouwen bij nieuwe ondernemingen."
        ),
        "zircon-dore" to GemTranslation(
