            descriptionCourte = "Een honingkleurig geeloranje, vaak verkregen door bruine zirkoon te verhitten.",
            descriptionLongue = "Gouden zirkoon beslaat het geel tot oranje kleurbereik van zirkoon; veel van de stenen op de markt worden thermisch behandeld vanuit Cambodjaanse bruine zirkoon om deze stabiele en aantrekkelijke tint te ontwikkelen.",
            particularites = "Hittebehandeling om de gouden kleur te stabiliseren is een oude en door de markt geaccepteerde praktijk.",
            inclusions = "Verdubbeling van de interne facetranden door sterke dubbele breking; kan metamicte zones vertonen afhankelijk van het gehalte aan radioactieve elementen.",
