        ),
        "chondrodite" to GemTranslation(
            nom = "Chondrodiet",
            descriptionCourte = "Een zeldzaam warm oranje, een weinig bekende neef van forsteriet.",
            descriptionLongue = "Chondrodiet, lid van de humietgroep, biedt oranje tot roodbruine tinten die zelden in geslepen stenen worden aangetroffen, voornamelijk afkomstig uit metamorfe marmers waar het geassocieerd is met spinel en forsteriet.",
            particularites = "Vaak aangetroffen in associatie met rode spinel en forsteriet in metamorfe marmers.",
            inclusions = "Minerale insluitsels die per vindplaats verschillen, vaak geassocieerd met het metamorfe kalksteen waarin het ontstaat.",
            lithotherapie = "Chondrodiet wordt in de lithotherapie gebruikt om innerlijke warmte en troost te bieden in tijden van twijfel."
        ),
        "grenat-spessartite" to GemTranslation(
            nom = "Spessartietgranaat",
            descriptionCourte = "Levendig \"mandarijn\"-oranje.",
            descriptionLongue = "In de jaren 1990 in commerciële hoeveelheden in Namibië ontdekt, biedt spessartiet een levendig, verzadigd oranje, bijgenaamd \"mandarijngranaat\". Het is tegenwoordig een van de meest gegeerde granaatvariëteiten.",
            particularites = "Natuurlijke kleur, nooit thermisch behandeld.",
            inclusions = "Karakteristieke vloeistofinsluitsels en fijne vezels, soms bijkomende kristallen zichtbaar onder een loep; Nigeriaanse of Namibische stenen zijn vaak zeer zuiver.",
            lithotherapie = "Een steen van dynamiek; spessartietgranaat wordt geassocieerd met creativiteit en ondernemersdrang."
        ),
        "topaze-imperiale" to GemTranslation(
            nom = "Keizertopaas",
            descriptionCourte = "De zeldzaamste variëteit van topaas.",
            descriptionLongue = "Historisch voorbehouden aan de Russische keizerlijke familie, vertoont keizertopaas een unieke oranje tot roze-oranje tint, bijna uitsluitend afkomstig uit de mijnen van Ouro Preto in Brazilië. Hij onderscheidt zich van blauwe topaas, die veel algemener voorkomt en doorgaans behandeld wordt.",
            particularites = "Perfecte splijting waarmee tijdens het slijpen en zetten rekening moet worden gehouden.",
            inclusions = "Twee- of driefasige vloeistofinsluitsels en fijne interne breuken; over het algemeen goede zuiverheid bij fraaie Braziliaanse stenen van edelsteenkwaliteit.",
            lithotherapie = "Keizertopaas zou persoonlijk succes, vrijgevigheid en openheid naar anderen bevorderen."
        ),
        "hessonite" to GemTranslation(
            nom = "Hessoniet",
            descriptionCourte = "Bijgenaamd de \"kaneelsteen\".",
            descriptionLongue = "Een variëteit van grossulaargranaat, rijk aan ijzer en mangaan, vertoont hessoniet een warme oranje kleur die aan kaneelstroop doet denken, met een intern glinstereffect (\"treacle effect\") door zijn karakteristieke insluitsels.",
            particularites = "Een typisch olieachtig tot honingachtig uiterlijk, veroorzaakt door interne insluitsels.",
            inclusions = "Vaak een troebel, \"gestoofd\" intern uiterlijk veroorzaakt door diffuse fijne vezeltjes en bijkomende kristallen, typisch voor Sri Lankaanse granaat.",
            lithotherapie = "Hessoniet wordt van oudsher gedragen om het zelfvertrouwen te versterken en zich te wapenen tegen overmatige zelfkritiek."
        ),
        "opale-de-feu" to GemTranslation(
