            descriptionCourte = "Transparant tot doorschijnend, een vlammende tint.",
            descriptionLongue = "In tegenstelling tot edelopaal ontleent vuuropaal zijn waarde aan zijn intense oranje tot rode kleur eerder dan aan kleurenspel, hoewel sommige stenen beide fenomenen vertonen.",
            particularites = "Een broze, poreuze steen, gevoelig voor thermische schokken.",
            inclusions = "Kleurenspel ontbreekt meestal; kan fijne interne breuken en een lichte melkachtige waas vertonen, typisch voor het verkiezelde materiaal.",
            lithotherapie = "Een steen van passie en motivatie; vuuropaal zou de drive herstellen die nodig is om aan nieuwe projecten te beginnen."
        ),
        "padparadscha" to GemTranslation(
            nom = "Padparadscha-saffier",
            descriptionCourte = "Het huwelijk van roze en oranje, een \"lotusbloem\"-tint.",
            descriptionLongue = "Zijn naam komt van het Singalese woord voor de lotusbloem. Dit korund combineert roze en oranje tonen in evenwichtige verhoudingen binnen één en dezelfde steen, een evenwicht dat in de natuur uiterst moeilijk te vinden is en dat er een van de meest gegeerde en duurste saffieren ter wereld van maakt.",
            particularites = "De precieze definitie van de tint blijft onderwerp van discussie tussen gemmologische laboratoria.",
            inclusions = "Subtiele kleurzonering tussen roze en oranje, fijne rutielzijde en bijkomende kristallen typisch voor Sri Lankaans korund.",
            lithotherapie = "Padparadscha-saffier symboliseert de harmonie tussen hart en verstand, en bevordert persoonlijke vervulling en sereniteit in de liefde."
