            descriptionLongue = "Carneool dankt zijn oranje tot rode tint aan ijzeroxiden. Gezet in scarabeeën en amuletten in het oude Egypte, blijft het vandaag een toegankelijke steen die veel wordt gebruikt in de juwelierskunst en voor intaglio's.",
            particularites = "Vaak verhit om de oranje tint vanuit bruin materiaal te versterken.",
            inclusions = "Kleuring afkomstig van fijn verspreide ijzeroxiden in de microkristallijne structuur; weinig afzonderlijk zichtbare insluitsels.",
            lithotherapie = "De steen van actie bij uitstek; carneool zou moed, motivatie en fysieke vitaliteit stimuleren."
        ),
        "pyrite" to GemTranslation(
            nom = "Pyriet",
            descriptionCourte = "\"Dwazengoud\" met metaalachtige gouden glans.",
            descriptionLongue = "Pyriet vormt kubische of octaëdrische kristallen van een intens metaalachtig messinggeel, lange tijd door onervaren goudzoekers voor goud aangezien. Al sinds het victoriaanse tijdperk gebruikt in geslepen juwelen (commercieel verkocht als \"marcasiet\").",
            particularites = "Oxideert en kan afbrokkelen (\"pyrietziekte\") bij langdurige blootstelling aan vocht.",
            lithotherapie = "Beschouwd als een steen van bescherming en overvloed; pyriet wordt gebruikt om zelfvertrouwen en initiatief te versterken."
        ),
        "scheelite" to GemTranslation(
            nom = "Scheeliet",
            descriptionCourte = "Een levendig blauwe fluorescentie onder UV en een dispersie hoger dan die van diamant.",
            descriptionLongue = "Scheeliet, het belangrijkste wolfraamerts, biedt geslepen een optische dispersie die hoger is dan die van diamant, maar zijn zachtheid maakt het voorbehouden aan verzamelaars. Het fluoresceert een karakteristiek elektrisch blauw onder kortgolvig UV-licht.",
            particularites = "Levendige blauwe fluorescentie onder kortgolvig UV, gebruikt door prospectors om het erts 's nachts op te sporen.",
            inclusions = "Karakteristieke intense blauwe fluorescentie onder UV; interne insluitsels zelden gedocumenteerd, aangezien geslepen stenen van edelsteenkwaliteit zeldzaam zijn.",
            lithotherapie = "Scheeliet wordt geassocieerd met mentale helderheid, nuttig om ideeën te ordenen en doordachte beslissingen te nemen."
        ),
        "tourmaline-jaune" to GemTranslation(
            nom = "Gele toermalijn",
            descriptionCourte = "Een stralend kanariegeel, de zeldzaamste van de toermalijnkleuren.",
            descriptionLongue = "Levendig gele toermalijn, \"canary\" genoemd, dankt zijn kleur aan mangaan en behoort tot de zeldzaamste en meest gegeerde tinten binnen de toermalijnfamilie, veel zeldzamer dan roze of groen.",
            particularites = "Van nature levendig gele kleur zonder behandeling, in tegenstelling tot veel commerciële toermalijntinten.",
            inclusions = "Katoendraad-trichieten en holle buisjes typisch voor de soort; over het algemeen zuiver bij stenen van juwelenkwaliteit.",
            lithotherapie = "Gele toermalijn zou levensvreugde en vertrouwen in de eigen capaciteiten stimuleren."
        ),
        "bastnasite" to GemTranslation(
            nom = "Bastnäsiet",
            descriptionCourte = "Een zeldzame-aardenmineraal met een stralende geelbruine kleur en sterke dispersie.",
            descriptionLongue = "Bastnäsiet is een belangrijke bron van zeldzame aarden (cerium, lanthaan), zelden geslepen wegens de schaarste aan kristallen van edelsteenkwaliteit, maar gewaardeerd door verzamelaars om zijn hoge dispersie en honing- tot geelbruine kleur.",
            particularites = "Een strategisch zeldzame-aardenerts; slijpbare edelsteenkwaliteit is anekdotisch.",
            inclusions = "Een zeldzame soort met zeldzame aarden; interne insluitsels weinig gedocumenteerd, aangezien geslepen stenen anekdotisch blijven.",
            lithotherapie = "Een zeldzaam mineraal; bastnäsiet wordt in de lithotherapie geassocieerd met het ontwaken van creativiteit en het stimuleren van het intellect."
        ),
        "orthose" to GemTranslation(
