            descriptionCourte = "Het gele kaliumveldspaat, verwant aan maansteen en amazoniet.",
            descriptionLongue = "Slijpbare orthoklaas, doorgaans een delicaat strogeel, komt bijna uitsluitend uit Madagaskar. Het is hetzelfde mineraal dat, in zijn melkachtig doorschijnende variëteit, door vergroeiing met albiet maansteen voortbrengt.",
            particularites = "Een vindplaats die vrijwel uitsluitend tot Madagaskar beperkt is voor transparante, slijpbare gele kwaliteit.",
            inclusions = "Kan fijne ontmengingslamellen en insluitsels vertonen die verantwoordelijk zijn voor een licht chatoyant effect bij sommige stenen.",
            lithotherapie = "Orthoklaas zou mentale helderheid en communicatie ondersteunen, en helpen om ideeën duidelijk te uiten."
        ),
        "saphir-jaune" to GemTranslation(
            nom = "Gele saffier",
            descriptionCourte = "Korund in elke tint behalve rood.",
            descriptionLongue = "De term \"saffier\" verwijst naar alle variëteiten van korund behalve rood (robijn). Gele saffier, gekleurd door sporen ijzer, is in Zuid-Azië zeer geliefd om zijn symbolische deugden die verband houden met wijsheid en voorspoed.",
            particularites = "Vaak verhit om de kleur te versterken en gelijkmatiger te maken.",
            inclusions = "Kleurzonering in hexagonale banden, ingesloten mineraalkristallen (rutiel, apatiet), sluiers van fijne deeltjes; zijde is doorgaans discreter dan bij blauwe saffier.",
            lithotherapie = "Gele saffier wordt van oudsher geassocieerd met voorspoed, wijsheid en professioneel succes."
        ),
        "citrine" to GemTranslation(
            nom = "Citrien",
            descriptionCourte = "Honinggeel tot goudgeel kwarts.",
            descriptionLongue = "Natuurlijke citrien is zeldzaam; de overgrote meerderheid van de stenen op de markt is afkomstig van verhitte amethist of rokerige kwarts, waarbij de kleur verandert in een stabiel goudgeel. De geboortesteen van november, geassocieerd met overvloed.",
            particularites = "Zeer betaalbaar en overvloedig; weinig tot geen zichtbare insluitsels.",
            inclusions = "Over het algemeen zeer zuiver; kan zeldzame negatieve kristallen of chevron-groeispoken vertonen, geërfd van verhitte amethist.",
            lithotherapie = "Bijgenaamd de steen van overvloed; citrien zou zelfvertrouwen, levensvreugde en materieel succes stimuleren."
        ),
        "heliodore" to GemTranslation(
            nom = "Heliodoor",
            descriptionCourte = "Gouden neef van smaragd en aquamarijn.",
            descriptionLongue = "Heliodoor, wiens naam \"geschenk van de zon\" betekent in het Grieks, is de gele tot geelgroene variëteit van beryl. Minder bekend dan zijn neven smaragd en aquamarijn, boeit hij door zijn stralende zuiverheid.",
            particularites = "Over het algemeen zeer zuiver, weinig insluitsels.",
            inclusions = "Holle buisjes evenwijdig aan de kristalas en zeldzame vloeistofinsluitsels, zoals andere berylen.",
            lithotherapie = "Heliodoor wordt geassocieerd met vreugde en vrijgevigheid, en bevordert een open geest en mentale helderheid."
        ),
        "chrysoberyl" to GemTranslation(
            nom = "Chrysoberil",
            descriptionCourte = "Hoge hardheid, verwant aan alexandriet.",
            descriptionLongue = "Met een hardheid van 8,5 is geelgroen chrysoberil een van de meest slijtvaste edelstenen na korund en diamant. Zijn kleurveranderende variëteit geeft aanleiding tot alexandriet, en zijn chatoyante variëteit tot kattenoog.",
            particularites = "Uitstekende slijtvastheid, ideaal voor dagelijks gebruik.",
            inclusions = "Kan karakteristieke cyclische tweelingvorming vertonen die een driestralig sterpatroon vormt, plus fijne vloeistofinsluitsels.",
            lithotherapie = "Chrysoberil zou onderscheidingsvermogen bevorderen en voorspoed aantrekken in persoonlijke en professionele aangelegenheden."
        ),
        "oeil-de-tigre" to GemTranslation(
            nom = "Tijgeroog",
            descriptionCourte = "Gouden chatoyance in een bewegende band.",
            descriptionLongue = "Tijgeroog dankt zijn gouden chatoyance aan vezels van crocidoliet (een asbestvariëteit) die zijn omgezet in kwarts (pseudomorfose). Geslepen als cabochon onthult het een stralende band die met het licht meebeweegt.",
            particularites = "Altijd geslepen als cabochon om de chatoyance (kattenoogeffect) te tonen.",
            lithotherapie = "Een steen van bescherming en zelfvertrouwen; tijgeroog wordt veel gebruikt om vastberadenheid te versterken en zich te wapenen tegen negatieve invloeden."
        ),
        "scapolite" to GemTranslation(
            nom = "Scapoliet",
            descriptionCourte = "Weinig bekend, variërend van honinggeel tot violet.",
            descriptionLongue = "Scapoliet vormt een reeks mineralen die bij het grote publiek weinig bekend zijn, geslepen tot doorschijnende honinggele tot roze edelstenen. Sommige Birmese kristallen vertonen chatoyance of een oranje fluorescentie onder UV.",
            particularites = "Sommige Birmese stenen vertonen een sterk kattenoogeffect.",
            inclusions = "Evenwijdige vezelige insluitsels die bij bepaalde Birmese stenen een chatoyant (kattenoog)effect kunnen veroorzaken.",
            lithotherapie = "Scapoliet wordt geassocieerd met persoonlijke discipline en motivatie, nuttig om projecten tot een goed einde te brengen."
        ),
        "malachite" to GemTranslation(
            nom = "Malachiet",
            descriptionCourte = "Het iconische groen van koper, in concentrische banden.",
            descriptionLongue = "Malachiet vormt botryoïdale massa's met concentrische banden van lichtgroen tot donkergroen, gekleurd door koper. Al sinds het oude Egypte gebruikt als pigment en sierksteen, tooit het zowel juwelen als meubilair (de zuilen van het Kremlin).",
            particularites = "Altijd geslepen als cabochon of gepolijst object; nooit gefacetteerd wegens zijn zachtheid en ondoorzichtigheid.",
            lithotherapie = "Een steen van transformatie; malachiet zou negatieve energieën absorberen en levensveranderingen zachtjes begeleiden."
        ),
        "dioptase" to GemTranslation(
            nom = "Dioptaas",
            descriptionCourte = "Een intens smaragdgroen dat wedijvert met smaragd zelf.",
            descriptionLongue = "Dioptaas vormt kleine kristallen in een zo intens smaragdgroen dat ze visueel wedijveren met echte smaragd, maar de grote broosheid en de perfecte splijting maken hem vrijwel uitsluitend voorbehouden aan verzamelaars.",
            particularites = "Perfecte splijting en grote broosheid: het facetteren ervan is een lapidaire krachttoer die zelden wordt ondernomen.",
            inclusions = "Kristallen vaak geassocieerd met dolomiet of calciet uit het gastgesteente; zelden gefacetteerd wegens de perfecte splijting.",
            lithotherapie = "Dioptaas wordt geassocieerd met diepe emotionele genezing, en bevordert vergeving en het verzachten van hartewonden."
        ),
        "libethenite" to GemTranslation(
            nom = "Libethenite",
            descriptionCourte = "Een olijfgroen tot donkergroen koperfosfaat, een zeldzaam verzamelmineraal.",
            descriptionLongue = "Libethenite vormt kleine prismatische of piramidale kristallen van olijfgroen tot donkergroen, soms bijna zwart, verenigd in druzige aggregaten op een geoxideerde matrix. Ontdekt in de 19e eeuw in Ľubietová (voorheen Libethen) in Slowakije, waaraan het zijn naam ontleent, ontstaat het in de oxidatiezone van kopervindplaatsen, vaak samen met malachiet en andere koperfosfaten. Geslepen als facetsteen blijft het uitzonderlijk: het is vooral een verzamelmineraal.",
            particularites = "Een secundair mineraal uit de verweringszone van kopervindplaatsen, vaak geassocieerd met malachiet en andere koperfosfaten; door zijn zeldzaamheid is het bijna uitsluitend voorbehouden aan mineraalverzamelaars.",
            lithotherapie = "Libethenite wordt in de lithotherapie soms geassocieerd met geaardheid en regeneratie, in lijn met koperhoudende mineralen die bekendstaan als energiegevend."
        ),
        "amazonite" to GemTranslation(
            nom = "Amazoniet",
            descriptionCourte = "Een ondoorzichtig blauwgroen gestreept met wit, ondanks een naam zonder verband met de Amazone.",
            descriptionLongue = "Amazoniet is een ondoorzichtige blauwgroene variëteit van microklien, gestreept met witte aders. Zijn naam doet denken aan de Amazonerivier, hoewel daar nooit een historische vindplaats is bevestigd — een van de blijvende mysteries van de mineralogie.",
            particularites = "Altijd geslepen als cabochon wegens zijn ondoorzichtigheid; gevoelig voor schokken langs zijn splijtvlakken.",
            inclusions = "Structuur van polysynthetische tweelingvorming, verantwoordelijk voor zijn karakteristieke gestreepte blauwgroene uiterlijk, soms doorkruist door fijne witte aders van kwarts of albiet.",
            lithotherapie = "Een steen van kalmering; amazoniet zou stress verzachten en oprechte communicatie met anderen vergemakkelijken."
        ),
        "chrysoprase" to GemTranslation(
            nom = "Chrysopraas",
            descriptionCourte = "Het levendigste appelgroen in de calcedoonfamilie.",
            descriptionLongue = "Chrysopraas is de calcedoonvariëteit met het meest verzadigde appelgroen, gekleurd door sporen nikkel. Al sinds de oudheid gewaardeerd, kende het een heropleving in de 18e eeuw, met name in het meubilair van Frederik de Grote van Pruisen.",
            particularites = "De kleur kan vervagen bij langdurige uitdroging of hoge hitte; blijft het best behouden wanneer licht vochtig.",
            inclusions = "Groene kleuring door nikkel verspreid in het microkristallijne silica; kan fijne witachtige adering vertonen.",
            lithotherapie = "Chrysopraas wordt van oudsher geassocieerd met hoop en optimisme, en opent het hart voor nieuwe perspectieven."
        ),
        "beryl-vert" to GemTranslation(
            nom = "Groene beryl",
            descriptionCourte = "Het \"gewone\" groen van beryl, zonder het chroom dat er een smaragd van zou maken.",
            descriptionLongue = "Gekleurd door ijzer in plaats van chroom of vanadium, heeft groene beryl in de strikte gemmologie geen recht op de naam \"smaragd\", maar biedt zuivere, stralende stenen tegen een veel toegankelijkere prijs.",
            particularites = "Onderscheiden van smaragd met de spectroscoop: afwezigheid van de absorptielijnen van chroom/vanadium.",
            inclusions = "Insluitsels van evenwijdige holle buisjes en incidentele bijkomende mineraalkristallen; over het algemeen zeer zuiver met het blote oog.",
            lithotherapie = "Groene beryl zou emotioneel evenwicht en vernieuwing brengen, en helpen om na een moeilijke periode de bladzijde om te slaan."
        ),
        "sillimanite" to GemTranslation(
            nom = "Sillimaniet",
            descriptionCourte = "Een weinig bekende neef van andalusiet en disteen, soms met een kattenoog.",
            descriptionLongue = "Sillimaniet, een polymorf van andalusiet en cyaniet (dezelfde formule, andere kristalstructuur), komt voor in blauwgroen tot bruin, soms met een chatoyant effect dat gewild is in cabochons.",
            particularites = "Kan een zeer uitgesproken kattenoogeffect vertonen wanneer geslepen als cabochon loodrecht op de vezels.",
            inclusions = "Vezelige insluitsels die een chatoyant (kattenoog)effect kunnen veroorzaken bij als cabochon geslepen stenen.",
            lithotherapie = "Sillimaniet wordt geassocieerd met mentale helderheid, een steun om orde te scheppen in gedachten en prioriteiten."
        ),
        "seraphinite" to GemTranslation(
            nom = "Serafiniet",
            descriptionCourte = "Een diep groen doorkruist met zijdeachtige zilveren veren.",
            descriptionLongue = "Serafiniet, de handelsnaam voor een variëteit van clinochloor, vertoont zilveren vederpatronen op een donkergroene ondergrond, die aan engelenvleugels doen denken — vandaar de naam. Altijd bewerkt als gepolijste cabochon om deze zijdeachtige glans te tonen.",
            particularites = "Uiterst zacht: het best voorbehouden aan juwelen die weinig aan schokken blootstaan (hangers, oorbellen).",
            lithotherapie = "Een steen van diepe genezing; serafiniet zou helpen om zich te bevrijden van herhalende patronen en innerlijke vernieuwing op gang te brengen."
        ),
        "grenat-grossulaire" to GemTranslation(
            nom = "Grossulaargranaat",
            descriptionCourte = "De groene tot geelgroene granaat, een licht gekleurde neef van tsavoriet en hessoniet.",
            descriptionLongue = "Grossulaar bestrijkt een breed bereik van kleurloos tot intens groen, via geelgroen (\"Mali-granaat\"), afhankelijk van de aanwezige sporen ijzer, mangaan of vanadium — tsavoriet en hessoniet zijn de bekendste variëteiten.",
            particularites = "De qua kleur meest diverse granaatfamilie, van kleurloos tot het diepe groen van tsavoriet.",
            inclusions = "Bijkomende kristallen die per vindplaats verschillen, met spanningshalo's rond kleine ingesloten kristallen.",
            lithotherapie = "Grossulaargranaat wordt geassocieerd met overvloed en vitaliteit, een steun tijdens periodes van persoonlijke wederopbouw."
        ),
        "diopside" to GemTranslation(
            nom = "Chroomdiopsied",
            descriptionCourte = "Een diep dennengroen door chroom, een neef van demantoïdgranaat.",
            descriptionLongue = "Chroomdiopsied dankt zijn intense groen, dicht bij dat van smaragd, aan sporen chroom. Aangetroffen in dezelfde vindplaatsen als diamanten (kimberlieten), dient het prospectors soms als indicatormineraal.",
            particularites = "Lage hardheid die voorzichtigheid vereist in juwelen; sommige stenen vertonen asterisme of een kattenoogeffect.",
            inclusions = "Fijne zwarte naaldvormige insluitsels (magnetiet of chromiet) en soms onder de loep zichtbare bijkomende kristallen.",
            lithotherapie = "Chroomdiopsied zou de verbinding met de natuur en het dagelijkse emotionele evenwicht bevorderen."
        ),
        "jade-nephrite" to GemTranslation(
            nom = "Nefrietjade",
            descriptionCourte = "De historische jade van China en Nieuw-Zeeland, te onderscheiden van jadeïet.",
            descriptionLongue = "Vóór de ontdekking van Birmese jadeïet in de 18e eeuw was alle jade bewerkt in het keizerlijke China, Nieuw-Zeeland (Maori-pounamu) en precolumbiaans Amerika nefriet — een amfibool met microscopisch verweven vezels die het een uitzonderlijke taaiheid geven.",
            particularites = "Een gevilte vezelstructuur die het schokbestendiger maakt dan jadeïet, ondanks een iets lagere hardheid.",
            lithotherapie = "Een steen van wijsheid en harmonie sinds het oude China; nefrietjade zou sereniteit, bescherming en een lang leven brengen."
        ),
        "maw-sit-sit" to GemTranslation(
            nom = "Maw-sit-sit",
            descriptionCourte = "Een elektrisch groen geaderd met zwart, genoemd naar een Birmees dorp.",
            descriptionLongue = "Maw-sit-sit, genoemd naar het Birmese dorp waar het in 1963 werd ontdekt, is een gesteente overwegend bestaande uit jadeïet en kosmochloor (een chroomhoudend pyroxeen) met een levendig groen doorkruist door zwarte aders, zeer gewild in Azië.",
            particularites = "Tot op heden de enige bekende vindplaats ter wereld, gelegen nabij de jadeïetmijnen van Hpakant.",
            lithotherapie = "Maw-sit-sit wordt geassocieerd met vernieuwing en de stroom van positieve energie in overgangsperiodes."
        ),
        "tourmaline-chrome" to GemTranslation(
            nom = "Chroomtoermalijn",
            descriptionCourte = "Een diep, verzadigd groen door chroom en vanadium, te onderscheiden van het \"klassieke\" groen.",
            descriptionLongue = "Gekleurd door chroom en vanadium in plaats van ijzer, vertoont chroomtoermalijn een verzadigder, dieper groen dan gewone groene toermalijn, met een uitgesproken dichroïsme tussen groen en bruingroen naargelang de kijkhoek.",
            particularites = "Uitgesproken dichroïsme: de oriëntatie van de tafel is bepalend om de meest verzadigde tint te tonen.",
            inclusions = "Fijne trichieten en incidentele kristallijne insluitsels, vergelijkbaar met andere groene toermalijnen.",
            lithotherapie = "Chroomtoermalijn zou vitaliteit stimuleren en tegelijk een open hart en mededogen bevorderen."
        ),
        "saphir-vert" to GemTranslation(
            nom = "Groene saffier",
            descriptionCourte = "Een subtiel groen, vaak dichroïsch, de meest betaalbare kleur van korund.",
            descriptionLongue = "Gekleurd door ijzer, vertoont groene saffier vaak een duidelijk dichroïsme (groen en geelgroen naargelang de hoek), een handtekening die helpt om hem van andere groene edelstenen te onderscheiden. Het is doorgaans de meest betaalbare kleur onder de saffieren.",
            particularites = "Uitgesproken dichroïsme tussen groen en geelgroen naargelang de kijkas, nuttig voor identificatie.",
            inclusions = "Karakteristieke kleurzonering in evenwijdige banden, fijne rutielzijde en bijkomende mineraalkristallen typisch voor korund.",
            lithotherapie = "Groene saffier wordt geassocieerd met innerlijk evenwicht en wijsheid, een steun om afstand te nemen."
        ),
        "emeraude" to GemTranslation(
            nom = "Smaragd",
            descriptionCourte = "Het meest gegeerde groen in de fijne juwelierskunst.",
            descriptionLongue = "Smaragd dankt zijn diepe groen aan chroom en/of vanadium. De natuurlijke insluitsels, bijgenaamd \"jardin\" (tuin), getuigen van de echtheid en worden doorgaans gestabiliseerd met een cederolie-behandeling, een op de markt geaccepteerde en verwachte praktijk.",
            particularites = "Oliebehandeling is vrijwel systematisch; een broze steen die zorgvuldige omgang vereist.",
            inclusions = "\"Jardin\": karakteristieke meerfasige insluitsels (vloeistof, gas, kristal), pyrietkristallen (Colombia), actinoliet of mica; natuurlijke scheurtjes doorgaans opgevuld met cederolie.",
            lithotherapie = "Een steen van liefde en wijsheid; smaragd wordt van oudsher geacht emotionele spanningen te verzachten en trouw en harmonie in relaties te bevorderen."
        ),
        "peridot" to GemTranslation(
            nom = "Peridoot",
            descriptionCourte = "Stralend olijfgroen, nooit behandeld.",
            descriptionLongue = "Peridoot is een van de weinige edelstenen die uit één enkele mineraalsoort bestaan (olivijn) en wordt nooit behandeld. Zijn sterke dubbele breking maakt de verdubbeling van de facetranden soms met het blote oog zichtbaar door de tafel van de steen.",
            particularites = "Dubbele breking zichtbaar met het blote oog; sommige stenen zijn afkomstig van meteorieten (pallasieten).",
            inclusions = "Frequente zwarte chromiet-insluitsels omgeven door een spanningsschijfje bijgenaamd \"waterlelie\", samen met fijne biotietmicakristallen.",
            lithotherapie = "Peridoot wordt geassocieerd met algemeen welzijn en loslaten, en helpt om wrok en rancune los te laten."
        ),
        "tsavorite" to GemTranslation(
            nom = "Tsavoriet",
            descriptionCourte = "Een duurzaam, onbehandeld alternatief voor smaragd.",
            descriptionLongue = "Ontdekt in 1967 nabij het Tsavo-nationaalpark in Kenia, dankt tsavoriet zijn groene kleur aan vanadium en chroom. Altijd onbehandeld, biedt het een schittering en zuiverheid die vaak superieur zijn aan die van smaragd.",
            particularites = "Nooit behandeld; beperkte vindplaatsen maken grote stenen zeer zeldzaam.",
            inclusions = "Fijne vezels en bijkomende kristallen (vaak magnetiet of grafiet); Oost-Afrikaanse stenen zijn over het algemeen van goede zuiverheid.",
            lithotherapie = "Tsavoriet zou vitaliteit en zelfvertrouwen stimuleren, een steun om uitdagingen energiek aan te gaan."
        ),
        "jade-jadeite" to GemTranslation(
            nom = "Jade (jadeïet)",
            descriptionCourte = "De heilige steen van de Chinese cultuur.",
            descriptionLongue = "Jadeïet vormt een microkristallijn aggregaat van uitzonderlijke taaiheid, wat het onderscheidt van nefriet, het andere mineraal dat \"jade\" wordt genoemd. Vereerd in China als \"steen van de hemel\", symboliseert het puurheid en deugd.",
            particularites = "Uiterst taai ondanks een matige hardheid; \"keizerlijke\" kwaliteit, een zeer zeldzaam doorschijnend groen.",
            lithotherapie = "Jade-jadeïet zou geluk en bescherming brengen, en tegelijk harmonie in relaties en innerlijke sereniteit bevorderen."
        ),
        "tourmaline-verte" to GemTranslation(
            nom = "Groene toermalijn (verdeliet)",
            descriptionCourte = "Groen gekleurd door ijzer of chroom.",
            descriptionLongue = "Verdeliet bestrijkt een breed palet aan groentinten, van licht mintgroen tot diep bosgroen, afhankelijk van de aanwezige sporen ijzer, chroom of vanadium. Het sterke pleochroïsme kan de tint merkbaar doen variëren naargelang de slijphoek.",
            particularites = "Sterke dubbele breking; slijpers oriënteren de ruwe steen om de kleur te optimaliseren.",
            inclusions = "Katoendraad-trichieten, holle buisjes evenwijdig aan de c-as en soms zichtbare kleurzonering.",
            lithotherapie = "Groene toermalijn wordt geassocieerd met emotioneel evenwicht en regeneratie, een steun na een periode van mentale vermoeidheid."
        ),
        "demantoide" to GemTranslation(
            nom = "Demantoïdgranaat",
            descriptionCourte = "Dispersie hoger dan die van diamant.",
            descriptionLongue = "Demantoïd is de meest gewaardeerde groene variëteit van andradietgranaat, gekleurd door chroom. Zijn dispersie (het \"vuur\") overtreft die van diamant, en zijn vezelige \"paardenstaart\"-insluitsels (byssoliet) zijn een door verzamelaars gezocht bewijs van echtheid.",
            particularites = "Uitzonderlijke optische dispersie; \"paardenstaart\"-insluitsels karakteristiek voor stenen uit de Oeral.",
            inclusions = "Radiaal vezelige \"paardenstaart\"-insluitsels (byssoliet), het kenmerk van Oeral-stenen en een zeer gewaardeerd bewijs van echtheid.",
            lithotherapie = "Demantoïdgranaat zou voorspoed aantrekken en de dagelijkse levensvreugde doen herleven."
        ),
        "uvarovite" to GemTranslation(
            nom = "Uvarovietgranaat",
            descriptionCourte = "Smaragdgroen in druzen van microkristallen.",
            descriptionLongue = "Uvarovite vormt vrijwel altijd piepkleine kristallen in druzen, zelden groot genoeg om als facetsteen te worden geslepen. Zijn intense smaragdgroen, te danken aan chroom, maakt er niettemin een zeer gegeerd verzamelstuk in ruwe staat van.",
            particularites = "Kristallen bijna altijd te klein voor facetslijpen; verzameld als ruwe druzen.",
            inclusions = "Komt meestal voor als piepkleine druzige kristallen; interne insluitsels weinig gedocumenteerd door de geringe afmetingen.",
            lithotherapie = "Uvarovite wordt geassocieerd met kalmering en een sterkere verbinding met de omringende natuur."
        ),
        "vesuvianite" to GemTranslation(
            nom = "Vesuvianiet (idocraas)",
            descriptionCourte = "Ontdekt op de hellingen van de Vesuvius.",
            descriptionLongue = "Voor het eerst beschreven op de lavastromen van de Vesuvius, biedt vesuvianiet (of idocraas) tinten van olijfgroen tot flessengroen. De massieve, compacte variëteit ervan, californiet, wordt soms gebruikt als vervanger van jade.",
            particularites = "De massieve variëteit californiet kan nefrietjade nabootsen.",
            inclusions = "Fijne korrelige insluitsels en bijkomende kristallen naargelang de vindplaats, vaak met een licht troebele interne structuur tot gevolg.",
            lithotherapie = "Vesuvianiet zou zelfoverstijging aanmoedigen en creativiteit in persoonlijke projecten stimuleren."
        ),
        "prehnite" to GemTranslation(
            nom = "Prehniet",
            descriptionCourte = "Doorschijnend pistachegroen.",
            descriptionLongue = "Als eerste mineraal genoemd naar een persoon (kolonel Von Prehn), vormt prehniet mamelonvormige aggregaten in pistache- tot geelgroen, geslepen als cabochon of soms als facetsteen wanneer het kristal het toelaat.",
            particularites = "Vaak geslepen als cabochon; soms verward met chrysopraas.",
            inclusions = "Karakteristieke vezelstralige structuur die een licht chatoyant uiterlijk geeft, soms met naaldvormige insluitsels van groene epidoot.",
            lithotherapie = "Prehniet wordt geassocieerd met sereniteit en het luisteren naar de eigen intuïtie, een steun bij meditatie."
        ),
        "chrysocolle" to GemTranslation(
            nom = "Chrysocolla",
            descriptionCourte = "Koperachtig blauwgroen, vaak in een kwartsmatrix.",
            descriptionLongue = "Gekleurd door koper, is chrysocolla zelden hard genoeg om alleen te worden geslepen: het wordt meestal gestabiliseerd in een kwartsmatrix (\"chrysocolla in kwarts\"), wat het de nodige hardheid voor de juwelierskunst geeft terwijl het zijn turkoois- tot diepgroene tinten behoudt.",
            particularites = "In zuivere vorm te zacht; voor juwelen geïmpregneerd met kwarts.",
            inclusions = "Vaak geassocieerd met gedeeltelijke verkiezeling (chrysocolla-in-kwarts), met insluitsels van natief koper of malachiet naargelang de vindplaats.",
            lithotherapie = "Chrysocolla zou zelfexpressie vergemakkelijken en emotionele spanningen rond communicatie verzachten."
        ),
        "variscite" to GemTranslation(
            nom = "Varisciet",
            descriptionCourte = "Doorschijnend appelgroen, een neef van turkoois.",
            descriptionLongue = "Als aluminiumfosfaat chemisch verwant aan turkoois, vertoont varisciet een geaderd appelgroen tot smaragdgroen, vaak doorkruist door fijne witte aders van crandalliet. Geslepen als cabochon blijft het een niche op de markt.",
            particularites = "Vaak verward met turkoois; altijd geslepen als cabochon.",
            lithotherapie = "Varisciet wordt geassocieerd met emotioneel evenwicht, en brengt een gevoel van troost en innerlijke geborgenheid."
        ),
        "serpentine" to GemTranslation(
            nom = "Serpentijn (bowenite)",
            descriptionCourte = "Een toegankelijk alternatief voor jade.",
            descriptionLongue = "Bowenite, een compacte en harde variëteit van serpentijn, wordt sinds de oudheid gebruikt als vervanger van nefrietjade in Nieuw-Zeeland (pounamu) en China. Het doorschijnende groen en de taaiheid maken er een gewaardeerde sierksteen van.",
            particularites = "De bowenite-variëteit, harder en doorschijnender, is de meest gezochte voor juwelen.",
            lithotherapie = "Serpentijn zou vernieuwing en geaardheid bevorderen, een steun tijdens periodes van persoonlijke wederopbouw."
        ),
        "grandidierite" to GemTranslation(
            nom = "Grandidieriet",
            descriptionCourte = "Een van de zeldzaamste edelstenen ter wereld, pleochroïsch blauwgroen.",
            descriptionLongue = "Ontdekt in Madagaskar in 1902 en genoemd ter ere van ontdekkingsreiziger Alfred Grandidier, telt grandidieriet slechts een handvol bekende transparante, slijpbare kristallen ter wereld. Het sterke pleochroïsme doet de kleur variëren van blauwgroen tot wit naargelang de kijkhoek.",
            particularites = "Minder dan twintig transparante geslepen stenen zijn wereldwijd geregistreerd.",
            inclusions = "Een zeer zeldzame soort; interne insluitsels weinig gedocumenteerd, aangezien de bekende geslepen stenen klein en gegeerd bij verzamelaars zijn.",
            lithotherapie = "Een zeldzaam en kostbaar mineraal; grandidieriet wordt in de lithotherapie geassocieerd met diepe sereniteit en het openen van het hart."
        ),
        "azurite" to GemTranslation(
            nom = "Azuriet",
            descriptionCourte = "Het diepe blauw van koper, vaak vergroeid met malachiet.",
            descriptionLongue = "Azuriet vormt kristallen en massa's van een intens diepblauw, gekleurd door koper. Op lange termijn onstabiel (het kan bij contact met vocht in malachiet veranderen), wordt het vooral bewerkt tot cabochons of decoratieve objecten, vaak samen met groene malachiet.",
            particularites = "Kan geleidelijk verweren tot malachiet (pseudomorfose); te beschermen tegen vocht en direct licht.",
            lithotherapie = "Azuriet zou intuïtie en mentale helderheid stimuleren, een steun bij reflectie en besluitvorming."
        ),
        "sodalite" to GemTranslation(
            nom = "Sodaliet",
            descriptionCourte = "Een diepblauw gestreept met wit, vaak verward met lapis lazuli.",
            descriptionLongue = "Sodaliet biedt een koningsblauw gestreept met witte calciet, vergelijkbaar met lapis lazuli maar zonder de gouden pyrietinsluitsels ervan. Sinds de ontdekking ervan in Groenland in de 19e eeuw gebruikt voor cabochons, inlegwerk en decoratieve objecten.",
            particularites = "Te onderscheiden van lapis lazuli door de afwezigheid van gouden pyrietvlekjes en een lagere dichtheid.",
            lithotherapie = "Sodaliet wordt geassocieerd met heldere communicatie en logica, en verzacht tegelijk mentale onrust."
        ),
        "larimar" to GemTranslation(
            nom = "Larimar",
            descriptionCourte = "Het unieke Caraïbische blauw van een pectoliet die op slechts één eiland wordt gevonden.",
            descriptionLongue = "Larimar is een variëteit van pectoliet in turkoois- tot hemelsblauw, die aan de wateren van de Caraïben doet denken; zijn kleur komt van sporen koper. Een vrijwel unieke vindplaats in de Dominicaanse Republiek maakt er een geografisch exclusieve edelsteen van.",
            particularites = "Vrijwel exclusieve vindplaats; de naam combineert \"Larissa\" (de dochter van de ontdekker) en \"mar\" (zee in het Spaans).",
            lithotherapie = "Een steen van sereniteit; larimar zou stress verzachten en oprechte, van het hart komende communicatie vergemakkelijken."
        ),
        "lazulite" to GemTranslation(
            nom = "Lazuliet",
            descriptionCourte = "Een diepblauw dat, ondanks de gelijkende naam, niet met lapis lazuli mag worden verward.",
            descriptionLongue = "Lazuliet vormt kristallen van een intens azuur- tot indigoblauw, fonetisch dicht bij lapis lazuli maar chemisch en mineralogisch geheel onverwant. Zeldzaam in slijpbare kwaliteit, wordt het vooral als specimen verzameld.",
            particularites = "Niet te verwarren met lazuriet (een bestanddeel van lapis lazuli) ondanks de gelijkenis in naam.",
            inclusions = "Vezelige insluitsels en bijkomende kristallen naargelang de vindplaats; zelden geslepen wegens zijn zeldzaamheid in edelsteenkwaliteit.",
            lithotherapie = "Lazuliet wordt geassocieerd met introspectie en mentale rust, een steun bij meditatie en innerlijke reflectie."
        ),
        "hauyne" to GemTranslation(
            nom = "Haüyniet",
            descriptionCourte = "Een intens ultramarijnblauw uit vulkanisch gesteente, een zeldzame neef van lapis lazuli.",
            descriptionLongue = "Haüyniet, genoemd naar de kristallograaf René Just Haüy, vertoont een diep ultramarijnblauw vergelijkbaar met de lazuriet in lapis lazuli, maar komt voor als geïsoleerde kristallen in vulkanische lava's en is uitzonderlijk zeldzaam in slijpbare vorm.",
            particularites = "Edelsteenkwaliteit kristallen zijn zelden groter dan enkele millimeters; geslepen stenen zijn uitzonderlijk.",
            inclusions = "Zeldzame kristallijne insluitsels naargelang de vulkanische vindplaats van herkomst; een uiterst zeldzame steen in slijpbare kwaliteit.",
            lithotherapie = "Haüyniet, een zeldzaam mineraal, wordt in de lithotherapie geassocieerd met authentieke zelfexpressie en vertrouwen in de eigen stem."
        ),
        "cavansite" to GemTranslation(
            nom = "Cavansiet",
            descriptionCourte = "Een elektrisch turkoois blauw in kristalrozetten, een ster op mineralenbeurzen.",
            descriptionLongue = "Cavansiet vormt rozetten van levendig turkoois-blauwe kristallen die basaltgeoden bekleden, vooral gewaardeerd door mineraalverzamelaars om zijn glasachtige glans en verzadigde kleur, zelden geslepen wegens de kleine afmetingen van de kristallen.",
            particularites = "Vrijwel exclusief voor de Deccan-basalten van India; nagenoeg nooit gefacetteerd.",
            inclusions = "Komt meestal voor als stervormig gegroepeerde sferolitische aggregaten; zelden geslepen als individuele zuivere steen.",
            lithotherapie = "Cavansiet zou spirituele ontwaking en helderheid van geest bevorderen in tijden van twijfel."
        ),
        "celestite" to GemTranslation(
            nom = "Celestiet",
            descriptionCourte = "Een bleek, hemels blauw; een zacht mineraal vooral verzameld als geode.",
            descriptionLongue = "Celestiet vormt tabulaire kristallen van een delicaat bleekblauw dat aan de hemel doet denken, vandaar de naam. Zijn extreme zachtheid maakt het vrijwel uitsluitend geschikt voor mineraalverzamelingen en decoratieve geodes eerder dan voor juwelen.",
            particularites = "Te zacht en te splijtbaar voor gebruik in juwelen; in essentie een verzamel- en decoratiesteen.",
            inclusions = "Vaak tabulaire, prismatische kristallen en fijne vloeistofinsluitsels; zelden geslepen wegens de broosheid (perfecte splijting, lage hardheid).",
            lithotherapie = "Een steen van diepe rust; celestiet zou een vredige slaap bevorderen en onrustige gedachten tot bedaren brengen."
        ),
        "euclase" to GemTranslation(
            nom = "Euclaas",
            descriptionCourte = "Een kristalhelder blauwgroen van opmerkelijke transparantie, berucht broos.",
            descriptionLongue = "Euclaas (\"gemakkelijk te splijten\" in het Grieks) ontleent zijn naam aan zijn perfecte splijting, die het uiterst delicaat maakt om te slijpen. Zijn zeer zuivere blauwgroene kristallen worden gezocht door verzamelaars van zeldzame geslepen stenen.",
            particularites = "Perfecte splijting in één richting: behoort tot de meest delicate edelstenen om te slijpen en te dragen.",
            inclusions = "Frequente vloeistofinsluitsels en fijne interne breuken, in overeenstemming met de perfecte splijting die het slijpen delicaat maakt.",
            lithotherapie = "Euclaas wordt geassocieerd met helderheid van expressie en sereniteit, een steun om zich met precisie te uiten."
        ),
        "topaze-bleue" to GemTranslation(
            nom = "Blauwe topaas",
            descriptionCourte = "Het diepblauw verkregen door bestraling en verhitting van een kleurloze topaas.",
            descriptionLongue = "Natuurlijke blauwe topaas is uiterst zeldzaam; vrijwel alle handelsstenen (\"Sky\", \"Swiss\", \"London Blue\") zijn afkomstig van kleurloze topaas die bestraald en vervolgens verhit is om stabiele, duurzame blauwtinten te ontwikkelen.",
            particularites = "De kleur wordt vrijwel systematisch verkregen door bestraling gevolgd door een thermische behandeling, en is stabiel en permanent.",
            inclusions = "Over het algemeen zeer zuiver (vaak het gevolg van een bestralingsbehandeling); zeldzame vloeistofinsluitsels of bijkomende kristallen.",
            lithotherapie = "Blauwe topaas zou een rustige communicatie bevorderen en helpen om emoties kalm te uiten."
        ),
        "tourmaline-bleue" to GemTranslation(
            nom = "Blauwe toermalijn (indigoliet)",
            descriptionCourte = "Een diepblauw dat verschilt van het koperige blauwgroen van Paraíba-toermalijn.",
            descriptionLongue = "Indigoliet is de blauwe tot blauwgroene variëteit van elbaïettoermalijn, gekleurd door ijzer, zonder het koper dat kenmerkend is voor Paraíba-toermalijn. De donkerdere, gedempte tinten maken er een aparte edelsteen van, soms verward met aquamarijn.",
            particularites = "Te onderscheiden van Paraíba-toermalijn door de afwezigheid van koper en een over het algemeen donkerdere tint.",
            inclusions = "Fijne trichieten en karakteristieke holle buisjes, met incidentele kristallijne insluitsels naargelang de vindplaats.",
            lithotherapie = "Blauwe toermalijn (indigoliet) wordt geassocieerd met zelfexpressie en het verzachten van communicatiegerelateerde spanning."
        ),
        "zircon-bleu" to GemTranslation(
            nom = "Blauwe zirkoon",
            descriptionCourte = "De meest gevraagde zirkoon op de markt, levendig blauw verkregen door verhitting.",
            descriptionLongue = "Blauwe zirkoon, de meest verhandelde kleur van de soort, wordt vrijwel systematisch verkregen door een thermische behandeling van Cambodjaanse bruine zirkoon. Zijn diamantachtige glans en sterke dispersie maken er een gewaardeerd en betaalbaar alternatief voor blauwe saffier van.",
            particularites = "Vrijwel systematische en stabiele hittebehandeling; sterke dispersie die dicht bij die van diamant ligt.",
            inclusions = "Doorgaans het gevolg van een hittebehandeling; karakteristieke verdubbeling van de interne facetranden en soms fijne spanningsbreuken.",
            lithotherapie = "Blauwe zirkoon zou mentale rust en helderheid brengen, een steun tijdens periodes van belangrijke reflectie."
        ),
        "hemimorphite" to GemTranslation(
            nom = "Hemimorfiet",
            descriptionCourte = "Blauwgroene botryoïdale vormingen die aan turkoois of chrysocolla doen denken.",
            descriptionLongue = "Hemimorfiet vormt blauwgroene botryoïdale aggregaten die vaak worden verward met turkoois of chrysocolla. Zijn naam (\"halve vorm\") komt van zijn kristallen, die aan elk uiteinde een andere symmetrie hebben, een kristallografische bijzonderheid.",
            particularites = "Wordt vaak visueel verward met chrysocolla of turkoois; identificatie vereist een hardheidstest.",
            inclusions = "Komt meestal voor als doorschijnende botryoïdale aggregaten; karakteristieke vezelige structuur.",
            lithotherapie = "Hemimorfiet wordt geassocieerd met authentieke communicatie en het helen van emotionele wonden rond zelfexpressie."
        ),
        "shattuckite" to GemTranslation(
            nom = "Shattuckiet",
            descriptionCourte = "Een diep, zijdeachtig blauw, een zeldzame neef van chrysocolla.",
            descriptionLongue = "Shattuckiet biedt een intens, zijdeachtig blauw in vezelige aggregaten, vaak samen met chrysocolla en malachiet aangetroffen in Namibische kopervindplaatsen. Altijd bewerkt als cabochon om zijn subtiele chatoyance te tonen.",
            particularites = "Te zacht voor facetslijpen; altijd gevormd als cabochon.",
            lithotherapie = "Shattuckiet zou de intuïtie versterken en een bewustere communicatie met zichzelf vergemakkelijken."
        ),
        "sapphirine" to GemTranslation(
            nom = "Sapphiriet",
            descriptionCourte = "Een ultrazeldzame blauwgrijze edelsteen, zonder verwantschap met korund.",
            descriptionLongue = "Ondanks zijn suggestieve naam is sapphiriet niet verwant aan korund: het is een apart silicaat in blauwgrijs tot paarsachtig, gevormd in metamorfe gesteenten van zeer hoge temperatuur, en behoort tot de zeldzaamste geslepen edelstenen ter wereld.",
            particularites = "Een van de zeldzaamste geslepen edelstenen ter wereld: er zijn slechts enkele tientallen geslepen stenen bekend.",
            inclusions = "Een zeer zeldzame soort; interne insluitsels weinig gedocumenteerd, aangezien er maar zeer weinig geslepen stenen bekend zijn.",
            lithotherapie = "Een zeldzaam mineraal; sapphiriet wordt in de lithotherapie geassocieerd met diepe rust en emotionele bescherming."
        ),
        "dumortierite" to GemTranslation(
            nom = "Dumortieriet",
            descriptionCourte = "Een intens blauwpaars in fijne vezels, vaak ingesloten in kwarts.",
            descriptionLongue = "Dumortieriet vormt diep blauwpaarse vezelige aggregaten, zelden in kristallen groot genoeg om apart te worden geslepen — men vindt het vaker als dichte insluitsels die een massief kwarts kleuren dat wordt gebruikt voor cabochons of kralen.",
            particularites = "Wordt vaker aangetroffen als massief kwarts met dichte dumortieriet-insluitsels dan als zuiver kristal.",
            inclusions = "Komt voor als dichte vezelige aggregaten, vaak ingesloten in kwarts (dumortieriet-kwarts), wat een blauw chatoyant effect geeft.",
            lithotherapie = "Dumortieriet zou geduld en mentale discipline ontwikkelen, een steun bij veeleisend leren."
        ),
        "afghanite" to GemTranslation(
            nom = "Afghaniet",
            descriptionCourte = "Een recent beschreven, lapis-achtig blauw, gevonden in dezelfde vindplaatsen als lapis lazuli.",
            descriptionLongue = "Wetenschappelijk beschreven in 1968, wordt afghaniet aangetroffen in dezelfde marmervindplaatsen als de Afghaanse lapis lazuli, met een vergelijkbare blauwe tint. Uiterst zeldzaam als geslepen steen, blijft het vooral een curiositeit voor verzamelaars.",
            particularites = "Late mineralogische ontdekking (1968); geslepen stenen behoren tot de zeldzaamste op de markt.",
            inclusions = "Zeldzame soort geassocieerd met Afghaanse lapis lazuli; kan fijne insluitsels van calciet of pyriet uit het gastgesteente bevatten.",
            lithotherapie = "Afghaniet wordt geassocieerd met diepe innerlijke rust en een vorm van zachte emotionele bescherming."
        ),
        "saphir-bleu" to GemTranslation(
            nom = "Blauwe saffier",
            descriptionCourte = "Het referentieblauw in de hoge juwelierskunst.",
            descriptionLongue = "Blauwe saffier dankt zijn kleur aan ijzer en titaan. Het \"fluwelen blauw\" van onbehandelde Kasjmir-stenen blijft de absolute referentie voor kenners, gevolgd door herkomsten uit Birma en Sri Lanka.",
            particularites = "Rutielinsluitsels als zijde, die asterisme kunnen veroorzaken (sterrensaffier).",
            inclusions = "Fijne rutielzijde, zirkoonkristallen omgeven door een spanningshalo, mica- of veldspaatkristallen, en kleurzonering in hexagonale banden, kenmerkend voor onverhitte stenen.",
            lithotherapie = "Een steen van wijsheid sinds de oudheid; blauwe saffier zou helderheid van geest, loyaliteit en het zoeken naar waarheid bevorderen."
        ),
        "saphir-auvergne" to GemTranslation(
            nom = "Saffier van Auvergne",
            descriptionCourte = "Een Franse korund met een diep blauwpaarse tint, gewonnen uit de vulkanische gronden van Auvergne.",
            descriptionLongue = "Gewonnen uit de vulkanische gronden van het Centraal Massief, met name rond Espaly-Saint-Marcel nabij Le Puy-en-Velay, zijn de saffieren van Auvergne een Franse korundvariëteit met een diep blauwpaarse tint. Zoals andere saffieren van basaltische oorsprong onderscheiden ze zich door een zeer uitgesproken kleur, maar de kristallen zijn meestal klein en zelden boven het karaat slijpbaar. Historisch ontgonnen in de 19e eeuw, blijven ze vandaag vooral een gezochte curiositeit voor verzamelaars en liefhebbers van de Franse gemmologie, eerder dan een commerciële bron van volume.",
            particularites = "Doorgaans kleine kristallen (zelden meer dan één karaat geslepen), met een zeer uitgesproken blauwpaarse kleur die typisch is voor saffieren van basaltische oorsprong.",
            inclusions = "Vaak rijk aan insluitsels die kenmerkend zijn voor basaltische saffieren: plagioklaas- en pyroxeenkristallen en een uitgesproken kleurzonering, bewijs van de Franse vulkanische oorsprong.",
            lithotherapie = "Zoals andere saffieren wordt de saffier van Auvergne van oudsher geassocieerd met wijsheid en helderheid van geest; zijn Franse herkomst maakt er een steen van die bijzonder gewaardeerd wordt door verzamelaars gehecht aan het nationale mineralogische erfgoed."
        ),
        "aigue-marine" to GemTranslation(
            nom = "Aquamarijn",
            descriptionCourte = "Kristalhelder \"zeewater\".",
            descriptionLongue = "Zijn naam, afkomstig van het Latijnse \"aqua marina\", roept zijn bleekblauwe tot blauwgroene kleur op die aan zeewater doet denken. Blauwe beryl onderscheidt zich door zijn grote zuiverheid, met zeer weinig met het blote oog zichtbare insluitsels.",
            particularites = "Vaak verhit om de groene component te verzachten en het blauw te versterken.",
            inclusions = "Over het algemeen zuiver; insluitsels van holle buisjes evenwijdig aan de c-as, zeldzame vloeistofinsluitsels en bijkomende kristallen.",
            lithotherapie = "De steen van zeelieden; aquamarijn wordt van oudsher geassocieerd met sereniteit, moed en een kalme communicatie, vooral tijdens reizen."
        ),
        "tanzanite" to GemTranslation(
            nom = "Tanzaniet",
            descriptionCourte = "Slechts één bron ter wereld, aan de voet van de Kilimanjaro.",
            descriptionLongue = "Ontdekt in 1967, bestaat tanzaniet alleen in de Merelani-zone in Tanzania. Zijn sterke trichroïsme laat blauw, paars en bordeaux zien naargelang de kijkhoek, voordat de standaardverhitting de gezochte blauwpaarse tint stabiliseert.",
            particularites = "Unieke en uitputtende vindplaats, beschouwd als een investeringssteen.",
            inclusions = "Sterk trichroïtisch pleochroïsme (blauw, paars, roodbruin); incidentele vloeistofinsluitsels en bijkomende kristallen, over het algemeen weinig talrijk na verhitting.",
            lithotherapie = "Tanzaniet zou innerlijke transformatie begeleiden en een sereen spiritueel ontwaken bevorderen."
        ),
        "lapis-lazuli" to GemTranslation(
            nom = "Lapis lazuli",
            descriptionCourte = "Diepblauw bezaaid met goud, gebruikt sinds de oudheid.",
            descriptionLongue = "Lapis lazuli is een gesteente dat voornamelijk uit lazuriet bestaat, samen met pyriet (gouden insluitsels) en calciet (witte aders). Al in het oude Egypte gebruikt en fijngemalen tot het pigment \"ultramarijnblauw\", tooit het al millennia sieraden en kunstvoorwerpen.",
            particularites = "De gouden pyrietinsluitsels, gelijkmatig verdeeld, zijn een teken van kwaliteit.",
            lithotherapie = "Een steen van wijsheid en waarheid sinds het oude Egypte; lapis lazuli zou het zelfvertrouwen en de helderheid van oordeel versterken."
        ),
        "turquoise" to GemTranslation(
            nom = "Turkoois",
            descriptionCourte = "Iconisch blauwgroen, geaderd met matrix.",
            descriptionLongue = "Al gebruikt sinds het oude Egypte en heilig voor talrijke Indiaanse culturen, dankt turkoois zijn blauw aan koper. Poreus en zacht, wordt het vaak gestabiliseerd door impregnatie met hars om bestand te zijn tegen gebruik in juwelen.",
            particularites = "Karakteristieke geaderde matrix; poreus, gevoelig voor cosmetica en chemische producten.",
            lithotherapie = "Al millennia een beschermsteen; turkoois zou sereniteit, oprechte communicatie en bescherming tijdens reizen bevorderen."
        ),
        "spinelle-bleu" to GemTranslation(
            nom = "Blauwe spinel",
            descriptionCourte = "Intens blauw, soms gekleurd door kobalt.",
            descriptionLongue = "Zeldzamer dan rode spinel, dankt blauwe spinel zijn meest gegeerde tint aan sporen kobalt, wat onder gloeilamplicht een diep, fluweelachtig blauw oplevert.",
            particularites = "Over het algemeen onbehandeld, in tegenstelling tot veel blauwe saffieren.",
            inclusions = "Bijkomende octaëdrische kristallen en wolken van fijne insluitsels, vergelijkbaar met andere natuurlijke, onbehandelde spinellen.",
            lithotherapie = "Blauwe spinel wordt geassocieerd met emotionele kalmering en vernieuwing na een periode van spanning."
        ),
        "paraiba-tourmaline" to GemTranslation(
            nom = "Paraíba-toermalijn",
            descriptionCourte = "Elektrisch \"neon\" blauwgroen, uniek in het minerale rijk.",
            descriptionLongue = "Ontdekt in 1989 in de Braziliaanse staat Paraíba, dankt deze toermalijn zijn ongeëvenaarde elektrische blauwgroen aan sporen koper en mangaan. Vergelijkbare vindplaatsen werden later gevonden in Mozambique en Nigeria. Het is een van de duurste kleuredelstenen ter wereld.",
            particularites = "\"Neon\"-kleur door koper, nooit waargenomen bij andere toermalijnen.",
            inclusions = "Over het algemeen van grote zuiverheid; fijne trichieten en incidentele holle buisjes, waarbij de hoge helderheid bijdraagt aan de waarde van de steen.",
            lithotherapie = "Paraíba-toermalijn zou een diepe vreugde en een vernieuwde vitaliteit stimuleren, in weerklank met zijn stralende kleur."
        ),
        "apatite-bleue" to GemTranslation(
            nom = "Neonblauwe apatiet",
            descriptionCourte = "Elektrisch turkoois blauw, weinig bekend bij het grote publiek.",
            descriptionLongue = "Neonblauwe apatiet, ontdekt in Madagaskar in de jaren 1990, biedt een zeer verzadigde turkooistint dicht bij die van Paraíba-toermalijn, voor een veel toegankelijker budget. De relatieve zachtheid beperkt het gebruik tot beschermde juwelen.",
            particularites = "Matige hardheid (5): het best voorbehouden aan oorbellen en hangers eerder dan aan ringen.",
            inclusions = "Frequente vloeistofinsluitsels en wolken van fijne deeltjes; een relatief broze steen die zorgvuldig geslepen moet worden.",
            lithotherapie = "Neonblauwe apatiet wordt geassocieerd met motivatie en helderheid van persoonlijke doelen, een steun om zich te herbronnen."
        ),
        "cyanite" to GemTranslation(
            nom = "Cyaniet (disteen)",
            descriptionCourte = "Wisselende hardheid naargelang de kristalas.",
            descriptionLongue = "Cyaniet (of disteen, \"twee weerstanden\" in het Grieks) is beroemd om zijn anisotrope hardheid: 4,5 in de lengterichting van het kristal, 6,5 loodrecht daarop. Zijn diepblauw doet soms aan saffier denken, tegen een veel toegankelijker prijs.",
            particularites = "Anisotrope hardheid die het slijpen delicaat maakt; perfecte splijting in één richting.",
            inclusions = "Perfecte splijting in twee richtingen die vaak interne breuken veroorzaakt; fijne vezelige insluitsels naargelang de vindplaats.",
            lithotherapie = "Cyaniet (disteen) zou innerlijke afstemming bevorderen en een vloeiende communicatie tussen hart en verstand."
        ),
        "benitoite" to GemTranslation(
            nom = "Benitoiet",
            descriptionCourte = "De officiële steen van Californië, opmerkelijke dispersie.",
            descriptionLongue = "Ontdekt in 1907 in San Benito County in Californië, fluoresceert benitoiet levendig blauw onder UV en vertoont een dispersie die hoger is dan die van diamant. De oorspronkelijke vindplaats blijft, meer dan een eeuw later, vrijwel de enige bron van edelsteenkwaliteit ter wereld.",
            particularites = "Levendige blauwe fluorescentie onder UV; vrijwel unieke vindplaats van edelsteenkwaliteit ter wereld.",
            inclusions = "Uiterst zeldzaam; kan fijne vloeistofinsluitsels vertonen, aangezien de meeste bekende geslepen stenen zeer klein blijven.",
            lithotherapie = "Een zeldzaam en kostbaar mineraal; benitoiet wordt in de lithotherapie geassocieerd met spirituele verheffing en helderheid van bewustzijn."
        ),
        "jeremejevite" to GemTranslation(
            nom = "Jeremejeviet",
            descriptionCourte = "Een uiterst zeldzaam aluminiumboraat, bleekblauw tot kleurloos.",
            descriptionLongue = "Beschreven in 1883 in Siberië en lange tijd onvindbaar in edelsteenkwaliteit, werd jeremejeviet pas in de jaren 1970 in Namibië in ontginbare hoeveelheden herontdekt. Het heldere bleekblauw en de zeldzaamheid maken er een verzamelaarssteen van die door kenners gegeerd wordt.",
            particularites = "Het grootste deel van de wereldwijde edelsteenproductie is afkomstig van één enkel Namibisch massief.",
            inclusions = "Een zeer zeldzame soort; interne insluitsels weinig gedocumenteerd, aangezien de slijpbare edelsteenkwaliteit beperkt in aantal is (voornamelijk Namibië).",
            lithotherapie = "Jeremejeviet, uiterst zeldzaam, wordt geassocieerd met een open geest en de verbinding met een vorm van hogere wijsheid."
        ),
        "violane" to GemTranslation(
            nom = "Violaan",
            descriptionCourte = "Een massieve, compacte variëteit van diopsied, diep blauwpaars.",
            descriptionLongue = "Violaan is een massieve, compacte variëteit van diopsied, in een uitgesproken blauwpaars dat dicht bij dat van sommige azurieten ligt, gekleurd door insluitsels van magnetiet. Altijd bewerkt als cabochon of gepolijst object.",
            particularites = "Historische typevindplaats in het Italiaanse Aostadal; altijd gevormd als cabochon.",
            lithotherapie = "Violaan, een paarse variëteit van diopsied, wordt geassocieerd met mentale kalmering en introspectie, een steun bij meditatie."
        ),
        "saphir-violet" to GemTranslation(
            nom = "Paarse saffier",
            descriptionCourte = "Een diep paars op de grens tussen blauwe saffier en robijn.",
            descriptionLongue = "Paarse saffier dankt zijn tint aan een mengeling van sporen ijzer, titaan en chroom, gelegen op de chromatische grens tussen blauwe saffier en robijn. Sommige stenen vertonen een gedeeltelijke kleurverandering naargelang de verlichting.",
            particularites = "Kan een lichte kleurverandering vertonen tussen daglicht en gloeilamplicht.",
            inclusions = "Kleurzonering in sectoren, rutielzijde en kristallijne insluitsels vergelijkbaar met andere korundvariëteiten.",
            lithotherapie = "Paarse saffier zou spiritualiteit en intuïtie bevorderen, een steun tijdens periodes van innerlijke bezinning."
        ),
        "purpurite" to GemTranslation(
            nom = "Purpuriet",
            descriptionCourte = "Een intens ondoorzichtig paarsrood, een zeldzame sierksteen van fosfaat.",
            descriptionLongue = "Purpuriet dankt zijn naam aan zijn uitgesproken purperen kleur, het resultaat van de verwering van mangaan- en ijzerfosfaten. Ondoorzichtig en relatief zacht, wordt het bewerkt tot cabochons voor de juwelierskunst en kunstvoorwerpen.",
            particularites = "De kleur kan aan het oppervlak vervagen bij langdurige blootstelling aan licht; te beschermen.",
            lithotherapie = "Purpuriet wordt geassocieerd met persoonlijke transformatie en innerlijke kracht in periodes van verandering."
        ),
        "hackmanite" to GemTranslation(
            nom = "Hackmaniet",
            descriptionCourte = "Een kameleonsteen die onder UV roze kleurt en vervolgens vervaagt in het licht.",
            descriptionLongue = "Hackmaniet is een tenebrescente variëteit van sodaliet: blootgesteld aan UV ontwikkelt het een roze-paarse tint die vervolgens geleidelijk vervaagt bij daglicht, een fascinerend en onder edelstenen uniek omkeerbaar verschijnsel.",
            particularites = "Omkeerbaar tenebrescentieverschijnsel: de kleur varieert naargelang recente blootstelling aan UV of licht.",
            inclusions = "Onderscheidt zich door zijn tenebrescentie (omkeerbare kleurverandering bij licht); wisselende kristallijne insluitsels naargelang de Afghaanse of Groenlandse vindplaats.",
            lithotherapie = "Hackmaniet zou de intuïtie stimuleren en een vorm van energetische bescherming bieden, vooral tijdens meditatie."
        ),
        "lepidolite" to GemTranslation(
            nom = "Lepidoliet",
            descriptionCourte = "De lila lithiumglimmer, vaak geassocieerd met roze toermalijn.",
            descriptionLongue = "Lepidoliet is een lithiumrijke glimmer met een karakteristieke lila tot malvekleurige tint, vaak aangetroffen in pegmatiet naast roze toermalijn en kunziet, waarmee het dezelfde lithiumchemie deelt.",
            particularites = "Te zacht en te bladerig voor gefacetteerde juwelen; gebruikt voor cabochons, kralen en decoratieve objecten.",
            lithotherapie = "Rijk aan natuurlijk lithium, staat lepidoliet van oudsher bekend om het verzachten van stress en angst en het bevorderen van een vredige slaap."
        ),
        "stichtite" to GemTranslation(
            nom = "Stichtiet",
            descriptionCourte = "Een lila paarsroze, vaak doorweven met groene serpentijn (atlantasiet).",
            descriptionLongue = "Stichtiet vormt lila paarsroze massa's, vaak vergroeid met groene serpentijn tot \"atlantasiet\", een zeer gewilde combinatie voor cabochons en sierstukken.",
            particularites = "Uiterst zacht: voorbehouden aan cabochons en decoratieve objecten die weinig aan schokken blootstaan.",
            inclusions = "Komt meestal voor als doorschijnende aggregaten met vezelige structuur, vaak geassocieerd met serpentijn.",
            lithotherapie = "Stichtiet wordt geassocieerd met mededogen voor zichzelf en anderen, en bevordert vergeving en emotionele kalmering."
        ),
        "amethyste" to GemTranslation(
            nom = "Amethist",
            descriptionCourte = "De steen van matigheid.",
            descriptionLongue = "Amethist dankt zijn paarse kleur aan sporen ijzer gecombineerd met natuurlijke bestraling. Overvloedig en toegankelijk, werd het niettemin eeuwenlang gedragen door adel en geestelijkheid, als symbool van soberheid en spiritualiteit.",
            particularites = "Kan verkleuren bij langdurige blootstelling aan zonlicht.",
            inclusions = "Kleurzonering in chevrons (Braziliaanse tweelingvorming), sluiers van fijne vloeistofinsluitsels, soms spookachtige groeikristallen.",
            lithotherapie = "Amethist is een van de bekendste stenen in de lithotherapie om stress te verzachten, een vredige slaap te bevorderen en meditatie en spiritualiteit te ondersteunen."
        ),
        "spinelle-violet" to GemTranslation(
            nom = "Paarse spinel",
            descriptionCourte = "Weerstand en schittering voor een duurzaam alternatief.",
            descriptionLongue = "Paarse spinel combineert een goede hardheid met de afwezigheid van splijting, wat er een zeer duurzaam alternatief voor amethist of paarse saffier van maakt, met een bijzonder levendige glasglans.",
            particularites = "Over het algemeen onbehandeld.",
            inclusions = "Kleine octaëdrische kristallen en fijne wolkachtige insluitsels typisch voor de soort, van nature onbehandeld.",
            lithotherapie = "Paarse spinel wordt geassocieerd met spirituele vernieuwing en innerlijke sereniteit."
        ),
        "iolite" to GemTranslation(
            nom = "Ioliet",
            descriptionCourte = "De \"saffier van de Vikingen\".",
            descriptionLongue = "Ioliet dankt zijn naam aan het Griekse \"ios\" (paars). Zijn spectaculaire pleochroïsme doet de kleur variëren van blauwpaars tot bijna kleurloos bleekgeel naargelang de kijkhoek, een eigenschap die Vikingzeevaarders naar verluidt gebruikten om zich te oriënteren.",
            particularites = "Zeer uitgesproken trichroïtisch pleochroïsme, bepalend voor de oriëntatie bij het slijpen.",
            inclusions = "Insluitsels van hematiet als fijne georiënteerde plaatjes, verantwoordelijk voor een chatoyant effect dat in sommige vindplaatsen \"bloodshot iolite\" wordt genoemd.",
            lithotherapie = "Gebruikt door Vikingzeevaarders om zich te oriënteren, zou ioliet de intuïtie en visionaire helderheid bij levenskeuzes versterken."
        ),
        "grenat-rhodolite-violet" to GemTranslation(
            nom = "Paarse rhodolietgranaat",
            descriptionCourte = "Purperen tint die verandert naargelang de verlichting.",
            descriptionLongue = "Sommige rhodolieten vertonen een bijzonder uitgesproken purperpaarse ondertoon bij natuurlijk licht, en bieden zo een betaalbaar alternatief voor de zeldzamere paarse stenen.",
            particularites = "Stabiele kleur, nooit behandeld.",
            inclusions = "Incidentele bijkomende kristallen en fijne interne vezeltjes, vergelijkbaar met die van de klassieke rhodoliet.",
            lithotherapie = "Deze paarse variëteit van rhodoliet wordt geassocieerd met het evenwicht tussen passie en emotionele sereniteit."
        ),
        "sugilite" to GemTranslation(
            nom = "Sugiliet",
            descriptionCourte = "Intens paars, populair geworden in de jaren 1970.",
            descriptionLongue = "In 1944 in Japan beschreven en later populair geworden dankzij de in de jaren 1970 ontdekte Zuid-Afrikaanse vindplaatsen, biedt sugiliet een ondoorzichtig tot doorschijnend paars tot dieppurper, geslepen als cabochon.",
            particularites = "Altijd geslepen als cabochon; de belangrijkste Zuid-Afrikaanse vindplaats is tegenwoordig uitgeput.",
            lithotherapie = "Sugiliet zou spirituele bescherming en troost bieden in periodes van rouw of grote emotionele vermoeidheid."
        ),
        "charoite" to GemTranslation(
            nom = "Charoïet",
            descriptionCourte = "Eén unieke vindplaats in Siberië.",
            descriptionLongue = "Pas in 1978 beschreven, is charoïet slechts van één vindplaats bekend, aan de oever van de rivier de Chara in Siberië. Het wervelende paars-witte patroon, veroorzaakt door verstrengelde kristalvezels, maakt er een onmiddellijk herkenbare sierksteen van.",
            particularites = "Unieke vindplaats ter wereld; karakteristiek wervelend patroon, altijd geslepen als cabochon.",
            inclusions = "Karakteristieke dichte vezelstralige structuur, doorkruist door aders van zwart mangaan (aegirien) en soms wit calciet.",
            lithotherapie = "Charoïet wordt geassocieerd met diepe innerlijke transformatie en de moed die nodig is om verandering het hoofd te bieden."
        ),
        "taaffeite" to GemTranslation(
            nom = "Taaffeiet",
            descriptionCourte = "Het eerste mineraal ontdekt in een reeds geslepen steen.",
            descriptionLongue = "Geïdentificeerd in 1945 door gemmoloog Richard Taaffe in een reeds gefacetteerde steen die ten onrechte als spinel was geclassificeerd, blijft taaffeiet een van de zeldzaamste edelstenen ter wereld, in delicate mauve tot lila tinten.",
            particularites = "Lang verward met spinel; onderscheidt zich door een dubbele breking die spinel niet heeft.",
            inclusions = "Een uiterst zeldzame soort, lang verward met spinel; interne insluitsels weinig gedocumenteerd.",
            lithotherapie = "Een uiterst zeldzaam mineraal; taaffeiet wordt in de lithotherapie geassocieerd met bewustzijnsontwaking en de eigenheid van het persoonlijke pad."
        ),
        "axinite" to GemTranslation(
            nom = "Axiniet",
            descriptionCourte = "Bijlvormige kristallen, sterk pleochroïsme.",
            descriptionLongue = "De naam komt van het Griekse \"axine\" (bijl), verwijzend naar de scherpe, afgeplatte vorm van de kristallen. Axiniet vertoont een sterk pleochroïsme van bruinpaars tot geelgroen naargelang de kijkhoek, gewaardeerd door verzamelaars van zeldzame stenen.",
            particularites = "Uitgesproken trichroïtisch pleochroïsme; kristallen historisch beschreven in Frankrijk (Dauphiné).",
            inclusions = "Fijne vloeistofinsluitsels en bijkomende kristallen naargelang de vindplaats; een steen met sterk pleochroïsme die met precisie wordt geslepen om de kleur te tonen.",
            lithotherapie = "Axiniet zou geaardheid en concentratie bevorderen, een steun om gecentreerd te blijven in roerige periodes."
        ),
        "cobaltocalcite" to GemTranslation(
            nom = "Kobaltcalciet",
            descriptionCourte = "Een levendig snoeproze, een door kobalt gekleurde calcietvariëteit.",
            descriptionLongue = "Kobaltcalciet (kobalthoudende calciet) vertoont een elektrisch levendig roze door sporen kobalt, en vormt botryoïdale korsten die zeer gewild zijn bij verzamelaars. De extreme zachtheid sluit elk gangbaar gebruik in juwelen uit.",
            particularites = "Uiterst zacht en gevoelig voor zuren zoals alle calciet; uitsluitend een verzamelaarssteen.",
            lithotherapie = "Kobaltcalciet wordt geassocieerd met zelfliefde en tederheid, een zachte emotionele steun in gevoelige periodes."
        ),
        "thulite" to GemTranslation(
            nom = "Thuliet",
            descriptionCourte = "De roze variëteit van zoïsiet, een neef van de blauwe tanzaniet.",
            descriptionLongue = "Thuliet is de roze tot roodroze variëteit van zoïsiet, gekleurd door mangaan — hetzelfde mineraal als tanzaniet, maar zonder de verhitting die bij die laatste het blauwpaars naar boven haalt. Ontdekt in Noorwegen, waaraan het zijn naam ontleent (Thule).",
            particularites = "Vrijwel altijd ondoorzichtig en gevormd als cabochon; transparante geslepen stenen zijn zeldzaam.",
            lithotherapie = "Thuliet zou vreugde en emotionele vitaliteit doen herleven, een steun om weer contact te maken met positieve emoties."
        ),
        "rhodonite" to GemTranslation(
            nom = "Rhodoniet",
            descriptionCourte = "Een diep roze geaderd met zwart mangaan.",
            descriptionLongue = "Rhodoniet biedt een uitgesproken roze tot roodroze, doorkruist door zwarte aders van mangaanoxiden die het een karakteristiek gemarmerd uiterlijk geven. Als nationale steen van Rusland siert het van oudsher de keizerlijke paleizen.",
            particularites = "Nationale steen van Rusland; de zwarte mangaanaders vormen een karakteristiek herkenningspatroon.",
            lithotherapie = "Rhodoniet wordt van oudsher geassocieerd met vergeving en het helen van emotionele wonden, vooral na een breuk."
        ),
        "topaze-rose" to GemTranslation(
            nom = "Roze topaas",
            descriptionCourte = "Het zeldzaamste natuurlijke roze van topaas, historisch gewonnen in Pakistan.",
            descriptionLongue = "Natuurlijke, onbehandelde roze topaas is veel zeldzamer dan blauwe of kleurloze topaas. De historische vindplaats Katlang in Pakistan leverde enkele van de mooiste stenen, met een delicate perzikroze tint.",
            particularites = "Het natuurlijke, onbehandelde roze is zeldzaam; te onderscheiden van roze topaas verkregen door thermische behandeling van bruine stenen.",
            inclusions = "Incidentele vloeistofinsluitsels en fijne interne breuken; de steen is meestal van goede zuiverheid.",
            lithotherapie = "Roze topaas zou zachtheid in relaties bevorderen en het hart openen voor oprechte liefde."
        ),
        "quartz-rose" to GemTranslation(
            nom = "Rozekwarts",
            descriptionCourte = "Het pastelroze kwarts, in elke traditie de steen van de liefde.",
            descriptionLongue = "Rozekwarts, gekleurd door sporen titaan, mangaan of microscopisch fijne vezelige dumortieriet-insluitsels, wordt in de meeste culturen geassocieerd met liefde en zachtheid. Transparante, slijpbare kristallen zijn zeldzaam; het meer voorkomende materiaal is massief en doorschijnend.",
            particularites = "Sommige stenen vertonen een zesstralig asterisme (sterrenrozekwarts), geslepen als cabochon.",
            inclusions = "Vaak licht troebel door fijne vezelige dumortieriet-insluitsels; kan een astereffect vertonen als cabochon.",
            lithotherapie = "De steen van onvoorwaardelijke liefde bij uitstek; rozekwarts zou hartewonden verzachten en tederheid jegens zichzelf en anderen bevorderen."
        ),
        "phosphosiderite" to GemTranslation(
            nom = "Fosfosideriet",
            descriptionCourte = "Een zacht roze-paars in mamelonvormige korsten, een neef van varisciet.",
            descriptionLongue = "Fosfosideriet vormt mamelonvormige korsten in lila roze tot paarsachtig, chemisch verwant aan groen varisciet maar gekleurd door ijzer. Altijd bewerkt als cabochon om zijn zijdeachtige glinstering te tonen.",
            particularites = "Zachtheid vergelijkbaar met die van varisciet; altijd gevormd als cabochon.",
            inclusions = "Karakteristieke dichte vezelstralige structuur met zijdeachtige glans, zelden geslepen wegens de beperkte doorschijnendheid.",
            lithotherapie = "Fosfosideriet wordt geassocieerd met loslaten en innerlijke zachtheid, een steun bij meditatie."
        ),
        "morganite" to GemTranslation(
            nom = "Morganiet",
            descriptionCourte = "Zacht roze tot perzikkleurig, benoemd in 1911.",
            descriptionLongue = "Vernoemd naar financier en verzamelaar J.P. Morgan door gemmoloog George Kunz, biedt morganiet een delicate roze tot perzikkleurige tint door mangaan. Zeer zuiver, wordt het vaak geslepen tot grote, spectaculaire stenen.",
            particularites = "Vaak verhit om een oranje ondertoon te verzachten en een puur roze naar voren te halen.",
            inclusions = "Verlengingsbuisjes evenwijdig aan de c-as en incidentele vloeistofinsluitsels; over het algemeen een zeer zuivere steen.",
            lithotherapie = "Morganiet zou het hart openen voor mededogen en zelfliefde, en emotionele onrust verzachten."
        ),
        "kunzite" to GemTranslation(
            nom = "Kunziet",
            descriptionCourte = "Uitgesproken pleochroïsme, een delicate steen.",
            descriptionLongue = "Ontdekt in 1902 en genoemd naar gemmoloog George Frederick Kunz, vertoont kunziet een verleidelijk lila roze. Het is echter gevoelig voor langdurig licht en thermische schokken, en het best voorbehouden aan incidenteel dragen.",
            particularites = "Duidelijke splijting in twee richtingen; te beschermen tegen langdurig direct licht.",
            inclusions = "Fijne vloeistofinsluitsels en een perfecte splijting in twee richtingen die het slijpen delicaat maakt; een schokgevoelige steen.",
            lithotherapie = "Kunziet wordt geassocieerd met onvoorwaardelijke liefde en diepe emotionele kalmering, een steun om opgestapelde spanningen los te laten."
        ),
        "saphir-rose" to GemTranslation(
            nom = "Roze saffier",
            descriptionCourte = "Op de grens tussen robijn en saffier.",
            descriptionLongue = "Gekleurd door chroom zoals robijn maar in mindere concentratie, bevindt roze saffier zich op de conventionele grens met robijn: voorbij een bepaalde verzadiging wordt de steen als robijn geherclassificeerd.",
            particularites = "De grens tussen robijn en roze saffier blijft onderwerp van discussie tussen gemmologische laboratoria.",
            inclusions = "Fijne rutielzijde, zirkoonkristallen met spanningshalo en kleurzonering in banden, vergelijkbaar met die van robijn, waarmee het dezelfde soort deelt.",
            lithotherapie = "Roze saffier zou oprechte liefde en harmonie in liefdesrelaties bevorderen."
        ),
        "tourmaline-rose" to GemTranslation(
            nom = "Roze toermalijn",
            descriptionCourte = "Mangaan voor een zachte tint.",
            descriptionLongue = "Minder verzadigd dan rubelliet, biedt roze toermalijn zachte tinten van bleekroze tot snoeproze, vaak geassocieerd met de twee- of drie-kleurige kristallen die kenmerkend zijn voor de groep.",
            particularites = "Vaak gezoneerde kristallen, aan de oorsprong van tweekleurige toermalijnen.",
            inclusions = "Katoendraad-trichieten en typische holle buisjes van de soort, soms met kristallijne mica-insluitsels.",
            lithotherapie = "Roze toermalijn wordt geassocieerd met tederheid en het helen van emotionele wonden rond liefde en gehechtheid."
        ),
        "rhodochrosite" to GemTranslation(
            nom = "Rhodochrosiet",
            descriptionCourte = "Concentrische roze en witte banden.",
            descriptionLongue = "Herkenbaar aan zijn concentrische roze-witte patronen die aan jaarringen doen denken, is rhodochrosiet een gewaardeerde sier- en verzamelsteen, maar te broos voor dagelijks gebruik in een ring.",
            particularites = "Zeer broos en gevoelig voor zuren; voorbehouden aan verzamelstukken of beschermde hangers.",
            lithotherapie = "Rhodochrosiet wordt geacht zelfliefde en de genezing van het innerlijke kind te bevorderen, een steun bij diepgaand emotioneel werk."
        ),
        "saphir-blanc" to GemTranslation(
            nom = "Witte saffier",
            descriptionCourte = "Korund zonder kleurend spoor, een discreet alternatief voor diamant.",
            descriptionLongue = "Zonder de metaalsporen die robijn of blauwe saffier kleuren, biedt witte saffier (of \"leucosaffier\") een schittering die dicht bij die van diamant ligt, tegen een veel lagere prijs, lang gebruikt als vervangsteen in horlogerie en juwelierskunst.",
            particularites = "Lagere dispersie dan diamant, maar bijna gelijke hardheid; uitstekende bestendigheid tegen dagelijkse slijtage.",
            inclusions = "Over het algemeen zeer zuiver met het blote oog; kan een lichte groeizonering en zeldzame bijkomende mineraalkristallen vertonen.",
            lithotherapie = "Witte saffier zou helderheid van geest en zuiverheid van intentie bevorderen bij belangrijke beslissingen."
        ),
        "topaze-blanche" to GemTranslation(
            nom = "Witte topaas",
            descriptionCourte = "Topaas in zijn zuiverste en meest voorkomende vorm, kleurloos en helder.",
            descriptionLongue = "Kleurloze topaas is in werkelijkheid de meest voorkomende kleur van de soort in de natuur — de blauwe topaas van de handel is er trouwens vrijwel altijd door behandeling uit voortgekomen. Helder en briljant, dient het ook als betaalbare vervangsteen voor diamant.",
            particularites = "Het meest overvloedige grondmateriaal voor de productie van door bestraling behandelde blauwe topaas.",
            inclusions = "Over het algemeen zeer zuiver; weinig met het blote oog zichtbare insluitsels.",
            lithotherapie = "Witte topaas wordt geassocieerd met mentale helderheid en het zoeken naar waarheid in levenskeuzes."
        ),
        "hambergite" to GemTranslation(
            nom = "Hambergiet",
            descriptionCourte = "Een kleurloze edelsteen van extreme zeldzaamheid, zowel broos als schitterend.",
            descriptionLongue = "Hambergiet is een nauwelijks getinte, kleurloze edelsteen, zeldzaam en schitterend, maar uiterst broos door een perfecte splijting die er een geduchte uitdaging voor slijpers van maakt — een van de minst geziene stenen op de markt.",
            particularites = "Perfecte splijting die het slijpen en het dragen als juweel bijzonder risicovol maakt; een verzamelaarssteen.",
            inclusions = "Een zeldzame soort met perfecte splijting; interne insluitsels weinig gedocumenteerd, aangezien stenen van edelsteenkwaliteit schaars blijven.",
            lithotherapie = "Hambergiet, een zeldzaam mineraal, wordt in de lithotherapie geassocieerd met mentale helderheid en concentratie."
        ),
        "petalite" to GemTranslation(
            nom = "Petaliet",
            descriptionCourte = "Een lithiumerts dat zelden wordt gefacetteerd, discreet en helder.",
            descriptionLongue = "Petaliet, een belangrijke bron van industrieel lithium, levert af en toe kleurloze tot licht getinte edelsteenkristallen op, geslepen voor verzamelaars eerder dan voor de brede juwelierskunst.",
            particularites = "Vooral gewonnen als lithiumerts; slijpbare edelsteenkwaliteit is anekdotisch.",
            inclusions = "Over het algemeen zeer zuiver; kan fijne vloeistofinsluitsels vertonen en een perfecte splijting die het slijpen delicaat maakt.",
            lithotherapie = "Petaliet zou een diepe sereniteit bevorderen, bijzonder gewaardeerd als steun bij meditatie."
        ),
        "phenakite" to GemTranslation(
            nom = "Fenakiet",
            descriptionCourte = "Een kleurloze edelsteen zo helder dat hij lange tijd verward werd met kwarts of diamant.",
            descriptionLongue = "De naam fenakiet (van het Griekse \"bedrieger\") komt van zijn misleidende gelijkenis met kwarts of zelfs met ruwe diamant. Zeldzaam en fraai geslepen, blijft het vooral gewaardeerd door ervaren verzamelaars.",
            particularites = "Zijn Griekse naam betekent \"bedrieger\", verwijzend naar de historische verwarring met kwarts.",
            inclusions = "Vaak van grote zuiverheid; zeldzame vloeistofinsluitsels of bijkomende kristallen naargelang de vindplaats.",
            lithotherapie = "Fenakiet wordt geassocieerd met bewustzijnsontwaking en grote spirituele helderheid, voorbehouden aan gevorderde meditatiepraktijken."
        ),
        "bytownite" to GemTranslation(
            nom = "Bytowniet",
            descriptionCourte = "Een zelden slijpbaar veldspaat, de calciumpool van de plagioklaasreeks.",
            descriptionLongue = "Bytowniet, rijk aan calcium binnen de plagioklaasreeks (tussen labradoriet en anorthiet), vormt uitzonderlijk heldere kristallen die zuiver genoeg zijn om te worden geslepen, voornamelijk in Congo en India.",
            particularites = "Calciumrijk lid van de plagioklaasreeks, tussen labradoriet en zuivere anorthiet.",
            inclusions = "Kan fijne ontmengingslamellen en koperinsluitsels vertonen die verantwoordelijk zijn voor een chatoyant effect bij sommige stenen die dicht bij labradoriet liggen.",
            lithotherapie = "Bytowniet zou een lichtgevende geaardheid bieden, tussen zachte bescherming en helderheid van geest in."
        ),
        "hyalite" to GemTranslation(
            nom = "Hyaliet",
            descriptionCourte = "Een kleurloze, transparante opaal die onder UV groen fluorescerend oplicht.",
            descriptionLongue = "Hyaliet is een niet-edele opaal, kleurloos en in dunne lagen volkomen transparant, beroemd om zijn levendig groene fluorescentie onder ultraviolet licht door sporen uranium — een schouwspel dat gewild is bij liefhebbers van fluorescerende mineralen.",
            particularites = "Levendig groene fluorescentie onder UV door sporen uranium, zonder opalescentie in tegenstelling tot edelopaal.",
            inclusions = "Een doorgaans kleurloze en zeer zuivere opaalvariëteit, soms fluorescerend onder UV door sporen uranium.",
            lithotherapie = "Deze kleurloze opaalvariëteit wordt geassocieerd met zuiverheid en lichtheid van geest."
        ),
        "anhydrite" to GemTranslation(
            nom = "Anhydriet",
            descriptionCourte = "Het watervrije calciumsulfaat, een droge neef van gips, zelden geslepen.",
            descriptionLongue = "Anhydriet, chemisch verwant aan gips maar zonder kristalwater, komt voor in tinten van kleurloos tot bleekblauw of paarsachtig. De zachtheid en splijting beperken het tot een discreet gebruik in verzamelingen.",
            particularites = "Hydrateert langzaam tot gips bij langdurig contact met water, een natuurlijk mineraal-omzettingsproces.",
            inclusions = "Kristallen vaak gesplijt in platen en fijne vloeistofinsluitsels; wegens broosheid zelden geslepen.",
            lithotherapie = "Anhydriet zou structuur en helderheid brengen in het ordenen van gedachten en dagelijkse zaken."
        ),
        "baryte" to GemTranslation(
            nom = "Bariet",
            descriptionCourte = "Een dicht en zacht mineraal, zelden geslepen maar spectaculair als kristal.",
            descriptionLongue = "Bariet (bariumsulfaat) dankt zijn naam aan zijn opmerkelijke dichtheid voor een niet-metallisch mineraal. De tabulaire kristallen, vaak kleurloos tot honinggeel, worden af en toe geslepen voor verzamelaars ondanks hun grote broosheid.",
            particularites = "Uitzonderlijk hoge dichtheid voor een niet-metallisch mineraal, gebruikt als identificatiecriterium.",
            inclusions = "Tabulaire kristallen vaak met insluitsels van fijne gekleurde deeltjes naargelang de vindplaats; wegens broosheid zelden geslepen.",
            lithotherapie = "Bariet wordt geassocieerd met geaardheid en emotionele stabiliteit, een steun in periodes van verandering."
        ),
        "aragonite" to GemTranslation(
            nom = "Aragoniet",
            descriptionCourte = "Het polymorf van kalksteen dat ook parels en koraal vormt.",
            descriptionLongue = "Aragoniet is het orthorhombische polymorf van calciumcarbonaat — dezelfde stof waaruit parels, schelpen en koraal bestaan. De terrestrische kristallen, vaak kleurloos tot bleekgeel, worden vooral in ruwe staat verzameld.",
            particularites = "Op zeer lange termijn instabiel: verandert langzaam in calciet, zijn stabielere polymorf.",
            inclusions = "Structuur vaak in karakteristieke pseudohexagonale tweelingvorming, met fijne vloeistofinsluitsels.",
            lithotherapie = "Aragoniet zou geaardheid en geduld bevorderen, en helpen om het natuurlijke ritme van de dingen te aanvaarden."
        ),
        "calcite" to GemTranslation(
            nom = "Calciet",
            descriptionCourte = "Het meest voorkomende mineraal van de aardkorst, af en toe geslepen.",
            descriptionLongue = "Calciet is een van de meest verspreide mineralen ter wereld, in een buitengewone verscheidenheid aan kristalvormen. Te zacht voor dagelijks gebruik, wordt het niettemin door verzamelaars geslepen om zijn spectaculaire dubbele breking (verdubbeling van het beeld door de steen heen).",
            particularites = "Extreme dubbele breking: een object gezien door een helder calcietkristal verschijnt verdubbeld.",
            inclusions = "Sterke dubbele breking die een duidelijke verdubbeling van de interne facetranden veroorzaakt, met het blote oog zichtbaar; perfecte splijting in drie richtingen.",
            lithotherapie = "Calciet wordt van oudsher gebruikt om de omringende energieën te zuiveren en mentale helderheid te brengen."
        ),
        "cerusite" to GemTranslation(
            nom = "Cerussiet",
            descriptionCourte = "Een looderts met een spectaculaire dispersie, zeldzaam als geslepen steen.",
            descriptionLongue = "Cerussiet, een looderts, heeft een optische dispersie die hoger is dan die van diamant, wat na het slijpen opmerkelijke vuurflitsen oplevert. De zeer hoge dichtheid en grote broosheid maken er uitsluitend een verzamelaarsedelsteen van.",
            particularites = "Optische dispersie hoger dan die van diamant; zeer hoge dichtheid, kenmerkend voor lood.",
            inclusions = "Sterke adamantijnen glans en sterke dispersie; frequente tweelingvorming in zesstralige sterren, een steen die delicaat is om te slijpen.",
            lithotherapie = "Cerussiet wordt geassocieerd met geaardheid en een zachte innerlijke transformatie."
        ),
        "montebrasite" to GemTranslation(
            nom = "Montebrasiet",
            descriptionCourte = "Een discrete lithiumhoudende edelsteen, neef van ambligoniet.",
            descriptionLongue = "Montebrasiet, een nauwe verwant van ambligoniet waarvan het zich alleen door zijn hydroxylgehalte onderscheidt, levert kleurloze tot bleekgele stenen op die vooral geslepen worden voor liefhebbers van lithiumhoudende zeldzaamheden.",
            particularites = "Historische en gelijknamige typevindplaats in de Creuse, Frankrijk, ontdekt in de 19e eeuw.",
            inclusions = "Incidentele vloeistofinsluitsels, vergelijkbaar met ambligoniet, waarvan het de hydroxylrijke variëteit is.",
            lithotherapie = "Montebrasiet zou helderheid van geest en onderscheidingsvermogen bevorderen bij belangrijke keuzes."
        ),
        "diamant" to GemTranslation(
            nom = "Diamant",
            descriptionCourte = "De hardste bekende edelsteen.",
            descriptionLongue = "Gevormd onder zeer hoge druk en temperatuur in de aardmantel, bestaat diamant uit zuiver gekristalliseerd koolstof. Zijn maximale hardheid, sterke dispersie (het \"vuur\") en diamantachtige glans maken er de referentiesteen van de hoge juwelierskunst van, beoordeeld volgens de \"4 C's\": karaat, kleur, zuiverheid (clarity) en slijpvorm (cut).",
            particularites = "Enige edelsteen met hardheid 10; certificering (GIA, HRD...) is verplicht voor belangrijke stenen.",
            inclusions = "Kristallen van diepe mineralen (granaat, olivijn), wolken van fijne deeltjes, veren (breuken), zwarte koolstofpuntjes en groeilijnen; de insluitsels bepalen de zuiverheid volgens de GIA-schaal.",
            lithotherapie = "Van oudsher symbool van kracht en zuiverheid; diamant zou de omringende energieën versterken en helderheid van intentie en zelfvertrouwen bevorderen."
        ),
        "zircon-blanc" to GemTranslation(
            nom = "Witte zirkoon",
            descriptionCourte = "Sterke dispersie, lange tijd gebruikt als vervanger voor diamant.",
            descriptionLongue = "Niet te verwarren met zirconia (een synthetisch materiaal), is zirkoon een natuurlijke edelsteen waarvan de sterke lichtdispersie wedijvert met die van diamant, wat er van oudsher een gewaardeerde vervangsteen van heeft gemaakt.",
            particularites = "Vaak verhit om kleurloos te worden vanuit bruine zirkoon; facetranden soms verdubbeld zichtbaar.",
            inclusions = "Sterke dubbele breking die een zichtbare verdubbeling van de achterste facetranden veroorzaakt; over het algemeen zuivere steen na verhitting.",
            lithotherapie = "Witte zirkoon wordt geassocieerd met helderheid van geest en zuiverheid van intentie, een lichtgevend alternatief voor diamant."
        ),
        "goshenite" to GemTranslation(
            nom = "Goshenite (witte beryl)",
            descriptionCourte = "De zeldzame, kleurloze variëteit van beryl.",
            descriptionLongue = "Commercieel minder gezocht dan zijn gekleurde neven (smaragd, aquamarijn, morganiet), is goshenite niettemin de zuiverste vorm van beryl, volledig vrij van kleurgevende elementen.",
            particularites = "Werd van oudsher gebruikt als brillenglas voordat optisch glas in gebruik kwam.",
            inclusions = "Het zuiverste lid van de berylfamilie; incidentele holle buisjes, zeer weinig zichtbare insluitsels.",
            lithotherapie = "Goshenite (kleurloze beryl) zou mentale helderheid bevorderen en helpen om situaties objectief te bekijken."
        ),
        "cristal-de-roche" to GemTranslation(
            nom = "Bergkristal",
            descriptionCourte = "Zuiver kwarts, transparant en overvloedig.",
            descriptionLongue = "Volledig kleurloos in zuivere staat, is bergkristal een van de meest overvloedige edelstenen op aarde. Het werd lang gebruikt voor het slijpen van waarzegbollen en optische onderdelen vóór het tijdperk van industrieel glas.",
            particularites = "Grote beschikbaarheid in grote kristallen, wat spectaculaire fantasieslijpvormen mogelijk maakt.",
            inclusions = "Over het algemeen volledig zuiver; kan decoratieve minerale insluitsels bevatten (rutiel, toermalijn, chloriet) of negatieve kristallen.",
            lithotherapie = "De \"meestersteen\" van de lithotherapie; bergkristal zou energieën versterken, gedachten verhelderen en de omringende ruimte zuiveren."
        ),
        "danburite" to GemTranslation(
            nom = "Danburiet",
            descriptionCourte = "Glans die dicht bij die van topaas ligt, weinig bekend.",
            descriptionLongue = "Ontdekt in Danbury (Connecticut) in de 19e eeuw, lijkt danburiet sterk op kleurloze of bleekgele topaas, maar zonder de perfecte splijting daarvan, wat het gemakkelijker maakt om te slijpen en dagelijks te dragen.",
            particularites = "Geen splijting in tegenstelling tot topaas, dat het visueel vaak imiteert.",
            inclusions = "Over het algemeen zeer zuiver; zeldzame vloeistofinsluitsels of bijkomende kristallen naargelang de Birmese of Mexicaanse vindplaats.",
            lithotherapie = "Danburiet wordt geassocieerd met een diepe sereniteit en het ontwaken van het hart, een zachte steun bij meditatie."
        ),
        "bois-fossilise" to GemTranslation(
            nom = "Versteend hout",
            descriptionCourte = "Boomhout, atoom voor atoom vervangen door silica, over miljoenen jaren.",
            descriptionLongue = "Versteend hout ontstaat door de geleidelijke verkiezeling van begraven boomstammen, waarbij kwarts de organische stof vervangt terwijl de oorspronkelijke houtstructuur behouden blijft, groeiringen inbegrepen. Gepolijst onthult het opmerkelijke natuurlijke patronen.",
            particularites = "Behoudt getrouw de oorspronkelijke celstructuur van het hout, soms zichtbaar onder de microscoop.",
            lithotherapie = "Versteend hout zou een diepe geaardheid bieden en herinneren aan het geduld dat elke duurzame transformatie vereist."
        ),
        "os-fossilise" to GemTranslation(
            nom = "Versteend bot",
            descriptionCourte = "Botten, soms van dinosaurussen, gemineraliseerd en gepolijst tot cabochons.",
            descriptionLongue = "Versteend bot, soms afkomstig van echte dinosaurusbotten, mineraliseert doordat de organische apatiet wordt vervangen door silica of andere mineralen, waarbij de karakteristieke poreuze structuur van botweefsel bewaard blijft, die na polijsten zichtbaar wordt.",
            particularites = "De oorspronkelijke poreuze celstructuur blijft zichtbaar na het polijsten van de steen, het kenmerk van fossiel botweefsel.",
            lithotherapie = "Geassocieerd met geaardheid en stabiliteit, zou versteend bot herinneren aan het belang van wortels en persoonlijke herinnering."
        ),
        "kornerupine" to GemTranslation(
            nom = "Kornerupien",
            descriptionCourte = "Een zeldzame groenbruine edelsteen met sterk pleochroïsme, soms met kleurverandering.",
            descriptionLongue = "Kornerupien vertoont een uitgesproken pleochroïsme (meerdere tinten zichtbaar naargelang de kijkhoek, van groen tot roodbruin), en sommige stenen uit Sri Lanka vertonen zelfs een kleurverandering vergelijkbaar met die van alexandriet.",
            particularites = "Uitgesproken trichroïtisch pleochroïsme, soms samen met een kleurverandering naargelang de lichtbron.",
            inclusions = "Sterk pleochroïsme samen met fijne vezelige insluitsels die een chatoyant effect kunnen geven bij sommige stenen.",
            lithotherapie = "Kornerupien, een discreet en zeldzaam mineraal, wordt geassocieerd met een zachte geaardheid en innerlijke stabiliteit."
        ),
        "hyperstene" to GemTranslation(
            nom = "Hyperstheen",
            descriptionCourte = "Een chatoyant brons-bruin, soms \"fluweelsteen\" genoemd.",
            descriptionLongue = "Hyperstheen vertoont een karakteristiek bronsgouden chatoyant effect (schiller) door interne lamellaire insluitsels, wat het de bijnaam \"fluweelsteen\" heeft opgeleverd. Het wordt meestal geslepen als cabochon om dit effect te tonen.",
            particularites = "Het bronsgouden chatoyante effect (schiller) is te danken aan interne ontmengingslamellen.",
            lithotherapie = "Hyperstheen zou introspectie bevorderen en een vorm van discrete energetische bescherming bieden."
        ),
        "paesine" to GemTranslation(
            nom = "Paesina",
            descriptionCourte = "Een kalksteengesteente waarvan de natuurlijke patronen aan miniatuurlandschappen doen denken.",
            descriptionLongue = "Paesina, of \"pietra paesina\" (landschapssteen), is een kalksteengesteente waarin infiltraties van ijzer- en mangaanoxiden op natuurlijke wijze patronen tekenen die aan landschappen, ruïnes of horizonnen doen denken — een volledig natuurlijk beeldend fenomeen, al sinds de Renaissance gewaardeerd in Toscane.",
            particularites = "Elke gepolijste plaat is uniek, als een natuurlijk schilderij gevormd door capillaire werking van metaaloxiden.",
            lithotherapie = "Bijgenaamd \"landschapssteen\", nodigt paesina uit tot contemplatie en een diepe innerlijke rust."
        ),
        "enstatite" to GemTranslation(
            nom = "Enstatiet",
            descriptionCourte = "Een groenbruin pyroxeen, soms met asterisme of kattenoog.",
            descriptionLongue = "Enstatiet, de zuiver magnesiumrijke pool van de orthopyroxenen, komt voor in groenbruine tot olijfkleurige tinten, af en toe met een vierstralig asterisme of een kattenoogeffect wanneer het als cabochon wordt geslepen.",
            particularites = "Kan een vierstralig asterisme vertonen, zeldzamer dan het klassieke zesstralige asterisme van korund.",
            inclusions = "Kan fijne georiënteerde vezelige insluitsels vertonen die een chatoyant effect geven bij als cabochon geslepen stenen.",
            lithotherapie = "Enstatiet wordt geassocieerd met geaardheid en een rustig en doordacht vermogen tot handelen."
        ),
        "sphalerite" to GemTranslation(
            nom = "Sfaleriet",
            descriptionCourte = "Het zinkerts met de hoogste dispersie van alle geslepen edelstenen.",
            descriptionLongue = "Sfaleriet, het belangrijkste zinkerts, heeft een recorddispersie onder de gefacetteerde edelstenen — hoger dan die van diamant — wat spectaculaire vuurflitsen oplevert. De extreme zachtheid maakt er eerder een verzamelaarssteen van dan een steen voor dagelijks gebruik.",
            particularites = "De hoogste dispersie van alle gangbaar verzamelde edelstenen, hoger dan die van diamant.",
            inclusions = "Zeer sterke dispersie en adamantijnen glans; perfecte splijting in zes richtingen die de steen delicaat maakt om te slijpen, zeldzame vloeistofinsluitsels.",
            lithotherapie = "Sfaleriet zou energetische geaardheid bevorderen en tegelijk de fysieke vitaliteit stimuleren."
        ),
        "rutile" to GemTranslation(
            nom = "Rutiel",
            descriptionCourte = "Het kristal verantwoordelijk voor de gouden insluitsels van rutielkwarts, zelden apart geslepen.",
            descriptionLongue = "Rutiel, een titaanoxide met metaalachtige glans, is vooral bekend als ingesloten mineraal in rutielkwarts, maar komt uitzonderlijk voor in kristallen die zuiver en transparant genoeg zijn om te worden geslepen, met een zeer hoge dispersie.",
            particularites = "Zeer hoge optische dispersie, dicht bij die van diamant, zelden benut wegens de donkere kleur.",
            lithotherapie = "Rutiel wordt van oudsher geassocieerd met het versterken van energieën en helderheid bij het nastreven van doelen."
        ),
        "quartz-fume" to GemTranslation(
            nom = "Rokerige kwarts",
            descriptionCourte = "Doorschijnend bruin, gekleurd door natuurlijke bestraling.",
            descriptionLongue = "Rokerige kwarts dankt zijn bruine tint aan gekleurde centra veroorzaakt door de natuurlijke radioactiviteit van het omringende gesteente, die inwerkt op sporen aluminium. Overvloedig en betaalbaar, wordt het vaak verhit om in citrien te veranderen.",
            particularites = "Kan verhit worden om geel te worden (citrien) of vervagen bij langdurige blootstelling aan licht.",
            inclusions = "Sluiers van fijne vloeistofinsluitsels en incidentele negatieve kristallen, vergelijkbaar met bergkristal.",
            lithotherapie = "Rokerige kwarts staat bekend om zijn krachtige geaardheidswerking, en zou helpen stress en dagelijkse spanningen te absorberen."
        ),
        "andalousite" to GemTranslation(
            nom = "Andalusiet",
            descriptionCourte = "Spectaculair groen-bruin-rood pleochroïsme.",
            descriptionLongue = "Andalusiet dankt zijn naam aan de Spaanse regio waar het voor het eerst werd beschreven. Zijn sterke trichroïtische pleochroïsme laat, naargelang de hoek, olijfgroene, roodbruine en gele tinten zien in dezelfde steen, een effect dat soms \"de arme man's alexandriet\" wordt genoemd.",
            particularites = "Zeer uitgesproken trichroïtisch pleochroïsme, bepalend voor de slijporiëntatie.",
            inclusions = "Sterk pleochroïsme met het blote oog zichtbaar (groen, bruin, rood naargelang de hoek); grafietinsluitsels soms kruisvormig gerangschikt (variëteit chiastoliet).",
            lithotherapie = "Andalusiet wordt geassocieerd met geaardheid en het vermogen om van perspectief te veranderen bij moeilijkheden."
        ),
        "sinhalite" to GemTranslation(
            nom = "Sinhaliet",
            descriptionCourte = "Lange tijd verward met bruine peridoot.",
            descriptionLongue = "Pas in 1952 als aparte soort geïdentificeerd, was sinhaliet daarvoor ten onrechte geclassificeerd als bruine peridoot in museumcollecties. De naam komt van \"Sinhala\", de oude naam van Sri Lanka, zijn belangrijkste bron.",
            particularites = "Tot 1952 verward met peridoot; altijd bruin, nooit groen in tegenstelling tot peridoot.",
            inclusions = "Fijne vloeistofinsluitsels en bijkomende kristallen naargelang de Sri Lankaanse vindplaats, een steen die historisch lang met peridoot werd verward.",
            lithotherapie = "Sinhaliet, een zeldzaam en discreet mineraal, wordt geassocieerd met innerlijke stabiliteit en doorzettingsvermogen."
        ),
        "staurotide" to GemTranslation(
            nom = "Staurotied (kruissteen)",
            descriptionCourte = "Beroemd om zijn kruisvormige tweelingen.",
            descriptionLongue = "Staurotied vormt van nature kruisvormige tweelingen, \"kruissteentjes\" of \"feeënsteentjes\" genoemd, van oudsher als amulet gedragen. Zelden gefacetteerd wegens de veelvoorkomende ondoorzichtigheid, wordt het vooral verzameld als ruwe tweelingvorming.",
            particularites = "Karakteristieke kruisvormige tweelingen; zelden gefacetteerd, vooral in ruwe staat verzameld.",
            lithotherapie = "Bijgenaamd kruissteen, wordt staurotied van oudsher gedragen als talisman voor bescherming en geluk."
        ),
        "sphene" to GemTranslation(
            nom = "Sfeen (titaniet)",
            descriptionCourte = "De hoogste dispersie na enkele uiterst zeldzame edelstenen.",
            descriptionLongue = "Sfeen vertoont een optische dispersie (het \"vuur\") die hoger is dan die van diamant, gecombineerd met een sterk bruin-groen-geel pleochroïsme. De relatieve zachtheid maakt er eerder een steen voor verzamelingen en weinig blootgestelde juwelen van.",
            particularites = "Uitzonderlijke dispersie, hoger dan die van diamant; vrij zacht en splijtbaar.",
            inclusions = "Zeer sterke dispersie (\"vuur\") vaak hoger dan die van diamant; wolken van fijne insluitsels en frequente bijkomende kristallen.",
            lithotherapie = "Sfeen (titaniet) zou mentale helderheid en creativiteit stimuleren, een steun voor projecten die precisie en inspiratie vereisen."
        ),
        "hematite" to GemTranslation(
            nom = "Hematiet",
            descriptionCourte = "Het metaalachtige grijszwarte ijzeroxide, al sinds de oudheid tot spiegelglans gepolijst.",
            descriptionLongue = "Hematiet wordt geslepen als cabochon of intaglio om een bijna spiegelende, metaalachtige grijszwarte glans te tonen. Al sinds het oude Egypte gebruikt als zegelsteen; het poeder geeft trouwens een karakteristiek rode streep — vandaar de naam, van het Griekse woord voor \"bloed\".",
            particularites = "Het poeder (de streep) is bloedrood ondanks het metaalachtige zwarte uiterlijk, de oorsprong van de Griekse naam.",
            lithotherapie = "De geaardheidssteen bij uitstek; hematiet zou innerlijke kracht versterken en beschermen tegen omringende negatieve energieën."
        ),
        "magnetite" to GemTranslation(
            nom = "Magnetiet",
            descriptionCourte = "De natuurlijke magneet van de oudheid, bekend als de steen van Magnesia.",
            descriptionLongue = "Magnetiet is het van nature magnetische mineraal bij uitstek, al sinds de oudheid bekend als \"magneetsteen\" of lodestone. Zelden gefacetteerd wegens de volledige ondoorzichtigheid, wordt het vooral bewerkt tot kralen en cabochons.",
            particularites = "Het enige van nature en sterk magnetische mineraal, een eigenschap die al in de oudheid werd gebruikt voor navigatie.",
            lithotherapie = "Magnetiet wordt geassocieerd met geaardheid en energetisch evenwicht, vaak gebruikt om lichaam en geest te herbronnen."
        ),
        "quartz-tourmaline" to GemTranslation(
            nom = "Toermalijnkwarts",
            descriptionCourte = "Naalden van zwarte toermalijn vastgelegd in helder kwarts.",
            descriptionLongue = "Toermalijnkwarts vangt naalden van zwarte toermalijn (schörl) in een verder helder kwartskristal, wat een opvallend grafisch patroon creëert dat zeer gewild is in zowel de lithotherapie als de hedendaagse juwelierskunst.",
            particularites = "De toermalijnnaalden blijven met het blote oog zichtbaar en creëren een grafisch patroon dat bij elke steen uniek is.",
            inclusions = "Zwarte naalden van toermalijn (schörl) verstrengeld in een helder kwarts.",
            lithotherapie = "Toermalijnkwarts combineert de beschermende krachten van zwarte toermalijn met de versterkende helderheid van bergkristal."
        ),
        "onyx" to GemTranslation(
            nom = "Onyx",
            descriptionCourte = "Zwarte en witte banden, vaak geverfd.",
            descriptionLongue = "Als microkristallijne kwartsvariëteit uit de calcedoonfamilie vertoont onyx van nature zwarte en witte banden. De meeste verhandelde stenen worden geverfd om een egaal, intens zwart te verkrijgen.",
            particularites = "Vrijwel systematisch kunstmatig geverfd om de kleur gelijkmatig te maken.",
            lithotherapie = "Onyx wordt van oudsher geassocieerd met innerlijke kracht, emotionele stabiliteit en bescherming tegen negatieve energieën."
        ),
        "spinelle-noir" to GemTranslation(
            nom = "Zwarte spinel",
            descriptionCourte = "Metaalachtige glans voor mannenjuwelen.",
            descriptionLongue = "Ondoorzichtig en diepzwart, wordt zwarte spinel bijzonder gewaardeerd in de hedendaagse herenjuwelierskunst om zijn bijna metaalachtige glans en zijn robuustheid bij dagelijks gebruik.",
            particularites = "Hoge krasbestendigheid, geschikt voor dagelijks gedragen juwelen.",
            lithotherapie = "Zwarte spinel zou een solide energetische bescherming bieden en tegelijk de geaardheid bevorderen."
        ),
        "tourmaline-noire" to GemTranslation(
            nom = "Zwarte toermalijn (schörl)",
            descriptionCourte = "De meest voorkomende toermalijnvariëteit.",
            descriptionLongue = "Rijk aan ijzer, is schörl veruit de meest verspreide toermalijnvariëteit op aarde. Ondoorzichtig en gitzwart, wordt het in de lithotherapie van oudsher geassocieerd met beschermende krachten.",
            particularites = "Vaak gestreepte prismatische kristallen, soms van grote afmetingen.",
            lithotherapie = "Zwarte toermalijn (schörl) is een van de meest gewaardeerde beschermstenen in de lithotherapie, verondersteld negatieve energieën te absorberen en de geaardheid te versterken."
        ),
        "obsidienne" to GemTranslation(
            nom = "Obsidiaan",
            descriptionCourte = "Natuurlijk glas met een scherpe breuk.",
            descriptionLongue = "Gevormd door de snelle afkoeling van silicarijke lava, is obsidiaan een amorf vulkanisch glas. De uiterst scherpe schelpvormige breuk maakte er al sinds de prehistorie een gereedschap van eerste keuze van, met name voor pijlpunten en messen.",
            particularites = "Sommige variëteiten vertonen een gouden of iriserende chatoyance (regenboogobsidiaan).",
            lithotherapie = "Obsidiaan zou een krachtige bescherming bieden en tegelijk verborgen waarheden onthullen, en een diepe innerlijke transformatie bevorderen."
        ),
        "rubis-etoile" to GemTranslation(
            nom = "Sterrenrobijn",
            descriptionCourte = "Een zesstralige ster die over het oppervlak van de cabochon glijdt.",
            descriptionLongue = "Sterrenrobijn dankt zijn asterisme aan fijne naaldvormige rutielinsluitsels (\"zijde\"), georiënteerd volgens de hexagonale symmetrie van korund, die het licht weerkaatsen in een bewegende zesstralige ster wanneer de steen als cabochon wordt geslepen.",
            particularites = "Asterisme alleen zichtbaar bij cabochonslijpen, nooit bij facetslijpen; vereist een puntvormige lichtbron.",
            inclusions = "Dankt zijn asterisme aan een dicht netwerk van rutielzijde georiënteerd volgens de drie assen van het kristal; de dichtheid en oriëntatie van deze zijde bepalen de scherpte van de zesstralige ster.",
            lithotherapie = "Sterrenrobijn combineert de beschermende krachten van robijn met een innerlijk gidsend vermogen, gesymboliseerd door zijn ster."
        ),
        "saphir-etoile" to GemTranslation(
            nom = "Sterrensaffier",
            descriptionCourte = "Een lichtgevende zesstralige ster, vaak in een blauwe of zwarte saffier.",
            descriptionLongue = "Zoals zijn neef de sterrenrobijn dankt de sterrensaffier zijn asterisme aan rutielzijde-insluitsels. Hij komt het vaakst voor in blauw of zwart, waarbij deze laatste kleur in verschillende Aziatische culturen van oudsher met bescherming wordt geassocieerd.",
            particularites = "Het meest gezochte asterisme vertoont zes perfect rechte, op de koepel van de cabochon gecentreerde stralen.",
            inclusions = "Dicht netwerk van rutielzijde georiënteerd volgens de drie assen van het korund, aan de oorsprong van het zichtbare zesstralige asterisme in cabochon.",
            lithotherapie = "Sterrensaffier zou spirituele begeleiding en bescherming bieden, waarbij zijn ster een te volgen pad symboliseert."
        ),
        "saphir-teal" to GemTranslation(
            nom = "Teal-saffier",
            descriptionCourte = "Een tweekleurig korund waarbij blauw en geel samensmelten tot een unieke blauwgroene tint.",
            descriptionLongue = "Teal-saffier dankt zijn karakteristieke blauwgroene kleur aan de aanwezigheid, binnen eenzelfde kristal, van blauwe groeizones (ijzer en titaan) en gele groeizones (ijzer), die visueel versmelten zodra de steen geslepen is. Deze natuurlijke tweekleurigheid, meer dan een egale tint, maakt er een zeer gewilde steen van bij liefhebbers van atypische kleuren, vooral uit de vindplaatsen van Montana.",
            particularites = "De blauw-gele tweekleurigheid, in ruwe staat zichtbaar als afzonderlijke zones, versmelt tot een homogene blauwgroene tint zodra de steen geslepen en georiënteerd is.",
            inclusions = "Karakteristieke blauwgroene kleurzonering in banden, discrete rutielzijde, bijkomende kristallen typisch voor Australisch korund.",
            lithotherapie = "Teal-saffier zou het evenwicht tussen rede en intuïtie bevorderen, waarbij zijn dubbele kleur de harmonie tussen twee complementaire energieën symboliseert."
        ),
        "diaspore-zultanite" to GemTranslation(
            nom = "Zultaniet",
            descriptionCourte = "Een kleurverandering van kaki-groen naar champagneroze, unieke vindplaats in Turkije.",
            descriptionLongue = "Verhandeld onder de naam \"zultaniet\", verandert deze diaspoorvariëteit van kleur: van olijf-kakigroen bij daglicht naar champagneroze tot paarsachtig bij gloeilamplicht, afkomstig van een unieke vindplaats in de Turkse bergen.",
            particularites = "Vrijwel unieke vindplaats ter wereld; de kleurverandering is subtieler dan die van alexandriet.",
            inclusions = "Sterk pleochroïsme (groen, geel, champagneroze naargelang de verlichting); fijne vloeistofinsluitsels en een perfecte splijting die het slijpen delicaat maakt.",
            lithotherapie = "Zultaniet, dat van kleur verandert naargelang het licht, wordt geassocieerd met aanpassingsvermogen en het vermogen tot persoonlijke transformatie."
        ),
        "ametrine" to GemTranslation(
            nom = "Ametrien",
            descriptionCourte = "Een tweekleurig kwarts waarin het paars van amethist en het geel van citrien één kristal delen.",
            descriptionLongue = "Ametrien dankt zijn tweekleurigheid aan een natuurlijk temperatuurverloop binnen het kwartskristal tijdens de groei: de warmere zones nemen de gele tint van citrien aan, terwijl de koelere zones het paars van amethist behouden. De Boliviaanse Anahí-mijn, lange tijd de enige commerciële bron ter wereld, is verbonden met een 17e-eeuwse legende die de ontdekking toeschrijft aan een Spaanse conquistador die trouwde met een lokale prinses en eigenares van de vindplaats.",
            particularites = "De slijpvorm is erop gericht het scherpe contrast tussen de twee kleurzones te benadrukken, vaak diagonaal verdeeld.",
            inclusions = "Duidelijke zonering tussen de paarse en gele sectoren, geërfd van de kristalstructuur van het kwarts, met de voor de soort typische vloeistofinsluitsels.",
            lithotherapie = "Ametrien zou de kalmerende krachten van amethist combineren met de stimulerende krachten van citrien, een evenwicht tussen innerlijke rust en creatieve energie."
        ),
        "grenat-couleur-changeante" to GemTranslation(
            nom = "Kleurveranderende granaat",
            descriptionCourte = "Blauwachtig groen overdag, roodpaars 's avonds, een weinig bekende rivaal van alexandriet.",
            descriptionLongue = "Sommige Oost-Afrikaanse pyroop-spessartietgranaten vertonen een spectaculaire kleurverandering, van blauwachtig groen of grijsgroen bij daglicht naar roodpaars bij gloeilamplicht, een zeldzaam fenomeen onder granaten.",
            particularites = "Vanadium, eerder dan chroom, is verantwoordelijk voor de kleurverandering bij deze granaat.",
            inclusions = "Bijkomende kristallen en fijne vezels typisch voor de pyroop-spessartietgranaat, waarvan hij de tussenliggende samenstelling deelt.",
            lithotherapie = "Deze kleurveranderende granaat symboliseert aanpassingsvermogen en het vermogen om zich te vernieuwen bij veranderende omstandigheden."
        ),
        "pietersite" to GemTranslation(
            nom = "Pietersiet",
            descriptionCourte = "Een chatoyante blauwgouden wervel, bijgenaamd \"stormoog\".",
            descriptionLongue = "Pietersiet is een kwarts met gebroken en opnieuw samengekit crocidolietvezel-insluitsels, die een chaotische blauwe, gouden en bruine chatoyance opleveren die aan een bevroren storm doet denken — vandaar de bijnaam \"stormoog\". Ontdekt in Namibië in 1962.",
            particularites = "Het chaotische chatoyante patroon, in tegenstelling tot het regelmatige patroon van tijgeroog, is het resultaat van een natuurlijke breuk van de interne vezels.",
            lithotherapie = "Bijgenaamd \"stormsteen\", zou pietersiet moed bieden bij snelle en onvoorziene veranderingen."
        ),
        "agate" to GemTranslation(
            nom = "Agaat",
            descriptionCourte = "De meest iconische gekleurde concentrische banding van kwarts.",
            descriptionLongue = "Agaat is een calcedoon met concentrische of evenwijdige banden in uiteenlopende kleuren, gevormd door opeenvolgende afzettingen van silica in vulkanische holtes. De talloze variëteiten (mos-, dendriet-, landschaps-, oogagaat...) maken er een van de meest verzamelde sierstenen ter wereld van.",
            particularites = "De banding wordt vaak versterkt door verven, een oude en algemeen aanvaarde marktpraktijk.",
            lithotherapie = "Agaat wordt van oudsher geassocieerd met emotioneel evenwicht, stabiliteit en een zachte dagelijkse bescherming."
        ),
        "jaspe" to GemTranslation(
            nom = "Jaspis",
            descriptionCourte = "Een ondoorzichtig kwarts met eindeloze patronen, van bloedrood tot landschapsgroen.",
            descriptionLongue = "Jaspis is een microkristallijn kwartsaggregaat dat ondoorzichtig wordt gemaakt door talrijke minerale onzuiverheden, met een vrijwel oneindig kleuren- en patronenpalet. \"Landschapsjaspis\" bootst hele natuurtaferelen na in de gepolijste steen.",
            particularites = "Volledige ondoorzichtigheid in tegenstelling tot agaat, te wijten aan de dichtheid van de ingesloten minerale onzuiverheden.",
            lithotherapie = "Jaspis wordt geassocieerd met geaardheid en doorzettingsvermogen, een steun om vol te houden in veeleisende periodes."
        ),
        "calcedoine" to GemTranslation(
            nom = "Calcedoon",
            descriptionCourte = "De microkristallijne vorm van kwarts, basis van agaat, carneool en onyx.",
            descriptionLongue = "Calcedoon is de cryptokristallijne vorm (microkristallen onzichtbaar voor het blote oog) van kwarts, waarvan agaat, carneool, chrysopraas en onyx zijn afgeleid. De doorschijnende blauwgrijze variëteit, \"blauwe calcedoon\" genoemd, is de meest gezochte in de juwelierskunst.",
            particularites = "Algemene term voor microkristallijn kwarts; agaat, carneool en onyx zijn er benoemde variëteiten van.",
            inclusions = "Vezelige microkristallijne structuur verantwoordelijk voor de melkachtige doorschijnendheid; zelden zichtbare insluitsels met het blote oog.",
            lithotherapie = "Calcedoon wordt geassocieerd met innerlijke harmonie en een kalme communicatie met de omgeving."
        ),
        "quartz-a-inclusions" to GemTranslation(
            nom = "Kwarts met insluitsels (jardin)",
            descriptionCourte = "Een miniatuur mineraal landschap, bevroren in een helder kristal.",
            descriptionLongue = "Talrijke variëteiten helder kwarts bevatten insluitsels van andere mineralen — chloriet, actinoliet, hematiet, rutiel, lithiofiliet, fuchsiet of pyriet naargelang de vindplaats — die unieke interne landschappen creëren, bijgenaamd \"tuinkwarts\" (lodoliet) of spookkwarts.",
            particularites = "Elke steen is uniek naargelang de aard van het ingesloten mineraal; nooit twee identieke kwartsen met insluitsels.",
            inclusions = "Bevat per definitie gevarieerde en overvloedige minerale insluitsels — chloriet, actinoliet, hematiet, rutiel, lithiofiliet of fuchsiet naargelang de vindplaats — die unieke interne landschappen creëren (\"jardin\").",
            lithotherapie = "Kwarts met insluitsels (het \"jardin\") nodigt uit tot introspectie, waarbij elk insluitsel een facet van de innerlijke wereld symboliseert."
        ),
        "quartz-rutile" to GemTranslation(
            nom = "Rutielkwarts",
            descriptionCourte = "Gouden \"venushaar\" bevroren in een helder bergkristal.",
            descriptionLongue = "Rutielkwarts sluit fijne gouden rutielnaalden in, poëtisch \"venushaar\" of \"liefdespijlen\" genoemd, wat een opvallend decoratief effect creëert dat zeer gewild is in de hedendaagse juwelierskunst.",
            particularites = "De rutielinsluitsels kunnen ook een kattenoogeffect opleveren wanneer het kristal als cabochon wordt geslepen.",
            inclusions = "Gouden of koperkleurige rutielnaalden die het kristal doorkruisen, soms in bundels of sterren gerangschikt.",
            lithotherapie = "Rutielkwarts combineert de versterkende krachten van bergkristal met een versterkte beschermende werking."
        ),
        "quartz-super-sept" to GemTranslation(
            nom = "Super Seven-kwarts",
            descriptionCourte = "Tot zeven mineralen verenigd in één kristal Braziliaanse amethist.",
            descriptionLongue = "De \"Super Seven\" (of melody stone) is een amethistkleurig kwarts uit Brazilië met tot zeven verschillende mineralen als insluitsels — onder andere cacoxeniet, goethiet, lepidocrociet, rutiel, hematiet — die bij elke steen unieke gouden en paarse patronen creëren.",
            particularites = "Unieke vindplaats ter wereld; de handelsnaam verwijst naar de zeven mineralen die aanwezig kunnen zijn.",
            inclusions = "Karakteristieke combinatie van zeven ingesloten mineralen (amethist, cacoxeniet, rutiel, goethiet, lepidocrociet, limoniet, hematiet), uniek voor de Braziliaanse vindplaats Bahia.",
            lithotherapie = "Als zeldzame combinatie van zeven mineralen zou Super Seven-kwarts diepe meditatie en een vorm van spirituele synthese bevorderen."
        ),
        "smithsonite" to GemTranslation(
            nom = "Smithsoniet",
            descriptionCourte = "Botryoïdale \"snoep\"-mamelons in een breed pastelpalet.",
            descriptionLongue = "Smithsoniet vormt botryoïdale massa's in zeer uiteenlopende pasteltinten — roze, blauw, groen, geel of mauve naargelang de aanwezige metaalsporen — waarvan het zijdeachtige, afgeronde oppervlak aan snoepjes doet denken, zeer gewild als cabochon.",
            particularites = "De kleur varieert naargelang het spoormetaal: koper (blauwgroen), kobalt (roze), cadmium (geel).",
            inclusions = "Komt meestal voor als doorschijnende botryoïdale aggregaten in pasteltinten; fijnkorrelige interne structuur.",
            lithotherapie = "Smithsoniet wordt geassocieerd met zachtheid en emotionele kalmering, een steun om prikkelbaarheid te temperen."
        ),
        "moldavite" to GemTranslation(
            nom = "Moldaviet",
            descriptionCourte = "Een olijfgroen glas ontstaan uit een meteorietinslag 15 miljoen jaar geleden.",
            descriptionLongue = "Moldaviet is een natuurlijk glas gevormd door de ogenblikkelijke smelting van aards gesteente bij een meteorietinslag in Beieren, ongeveer 15 miljoen jaar geleden, waarbij druppels gesmolten glas tot in Bohemen werden geslingerd, waar het vandaag wordt gevonden.",
            particularites = "Een geografisch unieke vindplaats ter wereld, verbonden met de Ries-inslagkrater in Beieren (Duitsland).",
            inclusions = "Natuurlijk glas van meteorietoorsprong, met doorgaans langwerpige gasbelletjes en filamenten van gesmolten silica (lechatelieriet).",
            lithotherapie = "Van meteorietoorsprong, zou moldaviet een intense innerlijke transformatie en een versneld spiritueel ontwaken teweegbrengen."
        ),
        "verre-libyque" to GemTranslation(
            nom = "Libisch glas",
            descriptionCourte = "Een doorschijnend geel woestijnglas, aanwezig in het borstsieraad van Toetanchamon.",
            descriptionLongue = "Libisch glas is een natuurlijk bleekgeel tot geelgroen glas, 29 miljoen jaar geleden gevormd in de Libische woestijn door een meteorietinslag of luchtexplosie. Een scarabee gesneden uit dit glas siert het funeraire borstsieraad van Toetanchamon.",
            particularites = "Al meer dan 3000 jaar geleden gebruikt door de oude Egyptische ambachtslieden, lang vóór de moderne wetenschappelijke beschrijving ervan.",
            inclusions = "Natuurlijk glas van meteoriet-/tektietoorsprong met gasbelletjes en soms fijne insluitsels van zirkoon of baddeleyiet.",
            lithotherapie = "Ontstaan uit een meteorietinslag miljoenen jaren geleden, wordt Libisch glas geassocieerd met helderheid van geest en een symbolische zonnebescherming."
        ),
        "alexandrite" to GemTranslation(
            nom = "Alexandriet",
            descriptionCourte = "Groen overdag, rood onder gloeilamplicht.",
            descriptionLongue = "Ontdekt in de Oeral in de 19e eeuw en genoemd naar de toekomstige tsaar Alexander II, verandert alexandriet spectaculair van kleur: smaragdgroen bij daglicht, purperrood onder gloeilamplicht. Stenen met een uitgesproken kleurverandering zijn uiterst zeldzaam en gegeerd.",
            particularites = "Het percentage kleurverandering is het belangrijkste waardecriterium.",
            inclusions = "Fijne vloeistofinsluitsels en bijkomende kristallen; net als bij klassiek chrysoberil kan cyclische tweelingvorming optreden die een driestralig sterpatroon vormt.",
            lithotherapie = "Alexandriet, dat van kleur verandert naargelang het licht, zou aanpassingsvermogen en het evenwicht tussen rede en intuïtie bevorderen."
        ),
        "tourmaline-pasteque" to GemTranslation(
            nom = "Watermeloentoermalijn",
            descriptionCourte = "Een roze kern omringd door groen, als een plakje fruit.",
            descriptionLongue = "Het resultaat van een kristalgroei in meerdere chemische stadia, vertoont watermeloentoermalijn een roze kern omgeven door een groene laag, dun gesneden om dit opvallende natuurlijke patroon te tonen.",
            particularites = "Meestal in dwarse plakjes gesneden om het \"watermeloen\"-effect te tonen.",
            inclusions = "Katoendraad-trichieten en holle buisjes typisch voor toermalijn, met een duidelijke kleurzonering tussen de roze kern en de groene rand.",
            lithotherapie = "Watermeloentoermalijn combineert de kalmerende krachten van roze met de beschermende energie van groen, en symboliseert het evenwicht tussen hart en actie."
        ),
        "labradorite" to GemTranslation(
            nom = "Labradoriet",
            descriptionCourte = "Bewegende metaalachtige weerschijn (labradorescentie).",
            descriptionLongue = "Labradoriet vertoont een optisch verschijnsel genaamd labradorescentie: blauwgroene, soms gouden of paarsachtige glinsteringen verschijnen en verdwijnen naargelang de kijkhoek, veroorzaakt door interne lamellen die het licht buigen.",
            particularites = "De oriëntatie bij het slijpen is bepalend om de labradorescentie te tonen.",
            inclusions = "Ontmengingslamellen die de geïriseerde chatoyance (labradorescentie) veroorzaken, soms samen met fijne insluitsels van ilmeniet of magnetiet.",
            lithotherapie = "Labradoriet zou een sterke energetische bescherming bieden en tegelijk de intuïtie en de dagelijkse magie stimuleren."
        ),
        "pierre-de-lune" to GemTranslation(
            nom = "Maansteen",
            descriptionCourte = "Zwevende blauwachtige gloed (adularescentie).",
            descriptionLongue = "Maansteen dankt zijn naam aan zijn zwevende blauwachtige gloed, de adularescentie, veroorzaakt door de vergroeiing van twee veldspaten op microscopische schaal die het licht buigen. De beste kwaliteiten met levendig blauw komen uit Sri Lanka.",
            particularites = "Optimale adularescentie wanneer de steen als cabochon geslepen wordt loodrecht op de interne lamellen.",
            inclusions = "Albiet-orthoklaas-ontmengingslamellen aan de oorsprong van de adularescentie, die blauwachtige gloed die onder het oppervlak lijkt te zweven.",
            lithotherapie = "Maansteen wordt van oudsher geassocieerd met intuïtie, gevoeligheid en nieuwe beginnen, in verband met de maancycli."
        ),
        "pierre-de-soleil" to GemTranslation(
            nom = "Zonnesteen",
            descriptionCourte = "Koperkleurige glinstering door koperinsluitsels.",
            descriptionLongue = "In tegenstelling tot maansteen dankt zonnesteen zijn warme glinstering (aventurescentie) aan fijne plaatjes koper of hematiet die in het kristal zijn ingesloten, wat oranje tot koperrode weerschijn oplevert naargelang de verlichting.",
            particularites = "Aventurescentie te danken aan plaatjes natief koper, in tegenstelling tot aventurijnkwarts dat door fuchsiet wordt gekleurd.",
            inclusions = "Plaatjes hematiet of goethiet als platte, georiënteerde insluitsels, verantwoordelijk voor de karakteristieke glinstering (aventurescentie).",
            lithotherapie = "Zonnesteen zou levensvreugde, vitaliteit en zelfvertrouwen brengen, naar het beeld van zijn warme glans."
        ),
        "fluorine" to GemTranslation(
            nom = "Fluoriet",
            descriptionCourte = "Het breedste kleurenpalet van het minerale rijk.",
            descriptionLongue = "Fluoriet kan in bijna elke kleur voorkomen, soms meerdere tegelijk in eenzelfde gezoneerd kristal. De zachtheid en de perfecte splijting in vier richtingen beperken het gebruik in juwelen, maar maken er een uiterst gewilde verzamelaarssteen van.",
            particularites = "Perfecte splijting in vier richtingen; karakteristieke fluorescentie onder UV, aan de oorsprong van de term \"fluorescentie\".",
            inclusions = "Soms zichtbare kleurzonering in banden, fijne vloeistofinsluitsels; perfecte splijting in vier richtingen maakt de steen broos om als juweel te dragen.",
            lithotherapie = "Fluoriet wordt veel gebruikt om concentratie en mentale helderheid te bevorderen, vooral tijdens periodes van studie of intensief werk."
        ),
        "ammolite" to GemTranslation(
            nom = "Ammoliet",
            descriptionCourte = "De bevroren iriseringen van fossiele ammonietschelpen.",
            descriptionLongue = "Ammoliet is afkomstig van het gefossiliseerde parelmoer van 70 miljoen jaar oude ammonietschelpen, vrijwel uitsluitend gevonden langs de Canadese Rocky Mountains. Het vertoont een veelkleurige irisatie vergelijkbaar met die van opaal, uniek onder de organische edelstenen.",
            particularites = "Fossiele organische edelsteen; vrijwel geografisch monopolie in het zuiden van Alberta.",
            lithotherapie = "Ammoliet, een fossiele organische edelsteen, wordt geassocieerd met geluk, vitaliteit en positieve transformatie."
        ),
        "corail" to GemTranslation(
            nom = "Rode koraal",
            descriptionCourte = "Het kalkskelet van een zeedier, kostbaar bloedrood sinds de oudheid.",
            descriptionLongue = "Kostbaar rood koraal is het vertakte kalkskelet van een klein koloniaal zeedier (Corallium rubrum), al sinds de oudheid geoogst in de Middellandse Zee. De overexploitatie ervan heeft er tegenwoordig een strikt gereguleerde organische edelsteen van gemaakt.",
            particularites = "Strikt gereguleerde oogst (CITES voor bepaalde soorten) wegens de historische overexploitatie van de riffen.",
            lithotherapie = "Rood koraal wordt van oudsher als bescherming gedragen, met name voor kinderen, en geassocieerd met vitaliteit en familie-energie."
        ),
        "perle-conque" to GemTranslation(
            nom = "Schelpparel (Lambi)",
            descriptionCourte = "Een vlamroze parel zonder parelmoer, afkomstig van de koningskroonslak uit de Caraïben.",
            descriptionLongue = "De schelpparel, of Lambi-parel, vormt zich in de koningskroonslak (Strombus gigas) uit de Caraïben. In tegenstelling tot klassieke parelmoerparels heeft ze geen parelmoer en dankt ze haar zijdeachtige glans en karakteristieke \"vlam\"-patroon aan de vezelige structuur van aragoniet.",
            particularites = "Karakteristiek \"vlam\"-patroon zichtbaar aan het oppervlak, uniek voor niet-parelmoerparels zoals de schelpparel of de meloenparel.",
            lithotherapie = "De schelpparel wordt geassocieerd met vrouwelijkheid, intuïtie en emotionele zachtheid."
        ),
        "ambre" to GemTranslation(
            nom = "Barnsteen",
            descriptionCourte = "Boomhars, miljoenen jaren geleden versteend.",
            descriptionLongue = "Barnsteen is hars van naaldbomen of bloeiende bomen, over miljoenen jaren versteend. De karakteristieke lichtheid en de soms spectaculaire insluitsels (insecten, planten) maakten er al sinds de prehistorie een kostbaar materiaal van, met name langs de Baltische \"barnsteenroute\".",
            particularites = "Drijft op zout water; kan fossiele insluitsels (insecten, planten) bevatten die zeer gewild zijn.",
            inclusions = "Kan spectaculaire fossiele insluitsels bevatten — insecten, planten, luchtbelletjes — ware vensters op oude ecosystemen, bijzonder gewild langs de Baltische route.",
            lithotherapie = "Barnsteen staat sinds de oudheid bekend om zijn kalmerende en beschermende krachten, en brengt warmte en emotioneel troost."
        ),
        "perle" to GemTranslation(
            nom = "Kweekparel",
            descriptionCourte = "De enige edelsteen voortgebracht door een levend wezen.",
            descriptionLongue = "Gevormd door een weekdier als reactie op een vreemd lichaam, bestaat de parel uit concentrische lagen parelmoer. Vrijwel alle vandaag verhandelde parels zijn kweekparels (Akoya, Tahiti, Zuidzee), waarbij menselijk ingrijpen beperkt blijft tot het inbrengen van de oorspronkelijke kern.",
            particularites = "Prijs wordt per stuk of per snoer beoordeeld naargelang grootte, vorm, glans en herkomst, niet per karaat.",
            inclusions = "Structuur in concentrische parelmoerlagen soms in doorschijning zichtbaar bij fijne parels; groei-onregelmatigheden eigen aan elke parel, teken van haar natuurlijke of gekweekte echtheid.",
            lithotherapie = "De kweekparel wordt geassocieerd met zuiverheid, wijsheid en harmonie in liefdesrelaties."
        ),
        "aventurine" to GemTranslation(
            nom = "Groene aventurijn",
            descriptionCourte = "Een fonkelend groen kwarts, bespikkeld met fuchsietplaatjes.",
            descriptionLongue = "Aventurijn dankt zijn naam en zijn karakteristieke glinstering (aventurescentie) aan fijne insluitsels van chroomhoudend mica (fuchsiet) of hematiet, verspreid in een massa microkristallijn kwarts. De groene variëteit, de meest voorkomende, wordt al eeuwenlang in grote hoeveelheden in India gewonnen.",
            particularites = "De aventurescentie, deze metaalachtige glinstering, ontstaat door de weerkaatsing van het licht op de ingesloten micaplaatjes; de term werd later overgenomen om het kunstglas aan te duiden dat dit effect nabootst.",
            inclusions = "Plaatjes fuchsiet (chroomhoudend mica) verspreid in het kwarts, verantwoordelijk voor de karakteristieke glinstering (aventurescentie).",
            lithotherapie = "Groene aventurijn geldt als geluksbrenger, geassocieerd met geluk, overvloed en emotionele kalmering."
        ),
        "epidote" to GemTranslation(
            nom = "Epidoot",
            descriptionCourte = "Een karakteristiek pistachegroen, zelden gefacetteerd wegens het uitgesproken pleochroïsme.",
            descriptionLongue = "Epidoot geeft zijn naam aan een hele mineraalgroep en komt voor in langwerpige kristallen van pistachegroen tot olijfgroen, waarbij de kleur van ijzer afkomstig is. Het sterke pleochroïsme, dat naargelang de kijkhoek verschillende tinten laat zien, bemoeilijkt het slijpen van stenen met een egale kleur.",
            particularites = "Met het sterke pleochroïsme (groen, geelbruin, rozeachtig kleurloos naargelang de hoek) moet bij het slijpen rekening worden gehouden om de mooiste gekleurde zijde te tonen.",
            inclusions = "Sterk pleochroïsme en fijne vezelige insluitsels of bijkomende kristallen naargelang de vindplaats.",
            lithotherapie = "Epidoot zou persoonlijke transformatie bevorderen en helpen om zich te bevrijden van herhalende emotionele patronen."
        ),
        "gaspeite" to GemTranslation(
            nom = "Gaspeïet",
            descriptionCourte = "Een ondoorzichtig appelgroen nikkelcarbonaat, zeldzaam en gezocht als cabochon.",
            descriptionLongue = "Gaspeïet is een nikkelcarbonaat van een ondoorzichtig appelgroen tot levendig groen, ontdekt op het schiereiland Gaspésie in Québec, waaraan het zijn naam ontleent. De Australische vindplaatsen die in edelsteenkwaliteit ontgonnen kunnen worden, vormen tegenwoordig de belangrijkste commerciële bron.",
            particularites = "Wordt van veraf vaak verward met turkoois of varisciet wegens de ondoorzichtige groene tint, maar onderscheidt zich door een uitgesprokener appelgroene kleur.",
            lithotherapie = "Gaspeïet wordt geassocieerd met overvloed en een zachte geaardheid, en bevordert stabiliteit in periodes van verandering."
        ),
        "hiddenite" to GemTranslation(
            nom = "Hiddeniet",
            descriptionCourte = "De groene variëteit van spodumeen, gekleurd door chroom, een neef van kunziet.",
            descriptionLongue = "Hiddeniet is de groene variëteit van spodumeen; zijn kleur is afkomstig van sporen chroom of vanadium — in tegenstelling tot de roze kunziet, die de zijne aan mangaan dankt. Ontdekt in North Carolina eind 19e eeuw, blijft het beste materiaal Amerikaans, hoewel Brazilië en Afghanistan er ook produceren.",
            particularites = "Zoals alle spodumeenvariëteiten heeft hij een perfecte splijting in twee richtingen en moet hij voorzichtig worden geslepen.",
            inclusions = "Fijne vloeistofinsluitsels en een perfecte splijting in twee richtingen, zoals kunziet waarmee hij dezelfde soort deelt (spodumeen).",
            lithotherapie = "Hiddeniet zou het hart openen voor mededogen en tegelijk helderheid en onderscheidingsvermogen brengen bij belangrijke beslissingen."
        ),
        "angelite" to GemTranslation(
            nom = "Angeliet",
            descriptionCourte = "De hemelsblauwe variëteit van anhydriet, zeer gewild in de lithotherapie.",
            descriptionLongue = "Angeliet is de handelsnaam voor een bleek, melkachtig blauwe anhydriet, gepolijst tot cabochons, kralen of decoratieve stukken. De kleur komt van sporen onzuiverheden in het watervrije calciumsulfaat, dat ontstaat wanneer gips onder druk wordt samengeperst en over lange geologische periodes zijn water verliest.",
            particularites = "Krast gemakkelijk en is gevoelig voor langdurig vocht, waardoor het langzaam kan hydrateren tot gips; te beschermen tegen water en schokken.",
            lithotherapie = "Angeliet wordt geassocieerd met communicatie, sereniteit en een vorm van kalme spirituele verbinding, vandaar de suggestieve naam."
        ),
        "oeil-de-faucon" to GemTranslation(
            nom = "Havikenoog",
            descriptionCourte = "De blauwgrijze, chatoyante variant van tijgeroog, niet-geoxideerd.",
            descriptionLongue = "Havikenoog deelt zijn oorsprong met tijgeroog: een pseudomorfose van kwarts na crocidoliet (blauw asbest), waarvan de evenwijdige vezels een zijdeachtige glinstering opleveren. In tegenstelling tot het gouden tijgeroog behoudt het de oorspronkelijke blauwgrijze tot blauwgroene tint, bij gebrek aan oxidatie van het ijzer.",
            particularites = "Hetzelfde blok ruw materiaal kan plaatselijk blauwgrijze zones (havikenoog) en gouden zones (tijgeroog) vertonen, naargelang de mate van ijzeroxidatie.",
            lithotherapie = "Havikenoog wordt van oudsher geassocieerd met helderziendheid, innerlijk zicht en het nemen van afstand bij complexe situaties."
        ),
        "howlite" to GemTranslation(
            nom = "Howliet",
            descriptionCourte = "Een witte steen geaderd met grijs, vaak geverfd om turkoois na te bootsen.",
            descriptionLongue = "Howliet komt van nature voor als witte knollen met een poreuze structuur, doorkruist door grijze tot zwarte aders die een marmering suggereren. De porositeit maakt het gemakkelijk te verven, wat er het meest gebruikte materiaal van maakt om turkoois goedkoop na te bootsen — een praktijk die vóór aankoop altijd gecontroleerd moet worden.",
            particularites = "De sterke porositeit maakt het bijzonder gevoelig voor verven, wat aan de basis ligt van talrijke imitaties van turkoois of lapis lazuli op de markt.",
            lithotherapie = "Howliet zou een onrustige geest kalmeren en een vrediger slaap bevorderen."
        ),
        "rhodizite" to GemTranslation(
            nom = "Rhodiziet",
            descriptionCourte = "Een uiterst zeldzaam boraat, een van de hardste mineralen na korund.",
            descriptionLongue = "Rhodiziet is een complex boraat van cesium, beryllium en aluminium, dat kristalliseert in piepkleine kleurloze tot bleekgele kristallen, vrijwel uitsluitend in Madagaskar. Zijn uitzonderlijke hardheid, dicht bij die van korund, en zijn extreme zeldzaamheid maken er een steen van die vrijwel uitsluitend voor ervaren verzamelaars bestemd is.",
            particularites = "Slijpbare kristallen groter dan één karaat zijn uitzonderlijk zeldzaam; de meeste geslepen stenen wegen minder dan 0,5 karaat.",
            inclusions = "Een zeer zeldzame soort die voorkomt in kleine dodecaëdrische kristallen; interne insluitsels weinig gedocumenteerd.",
            lithotherapie = "Rhodiziet wordt geassocieerd met energetische harmonisatie en de versterking van positieve intenties."
        ),
        "sanidine" to GemTranslation(
            nom = "Sanidien",
            descriptionCourte = "Een kleurloos tot bleekgeel vulkanisch veldspaat, snel aan de oppervlakte gekristalliseerd.",
            descriptionLongue = "Sanidien is de hogetemperatuurvorm van kaliumveldspaat, die snel kristalliseert in vulkanische gesteenten en lava's, wat het onderscheidt van orthoklaas, dat langzamer in de diepte wordt gevormd. De meest gezochte heldere, slijpbare kristallen komen uit de vulkanische uitwerpselen van de Eifel in Duitsland.",
            particularites = "Onderscheidt zich van orthoklaas door zijn snelle vulkanische vorming en zijn meer ongeordende atomaire structuur; beide delen dezelfde chemische formule.",
            inclusions = "Over het algemeen zuiver, met zeldzame bijkomende kristallijne insluitsels naargelang de vulkanische vindplaats van herkomst.",
            lithotherapie = "Sanidien wordt geassocieerd met mentale helderheid en spontaniteit, in weerklank met zijn snelle vorming in vulkanisch gesteente."
        ),
        "tremolite" to GemTranslation(
            nom = "Tremoliet",
            descriptionCourte = "Een witte tot grijze amfibool, waarvan de roze variëteit veel gezochter is.",
            descriptionLongue = "Tremoliet is een calcium-magnesiumamfibool die de magnesiumrijke pool vormt van de tremoliet-actinolietreeks; in dichte vezelige vorm is het een van de bestanddelen van nefriet. De edelsteenvariëteit, meestal wit, grijs of kleurloos, wordt zelden geslepen, met uitzondering van de zeldzame paarse variëteit, hexagoniet genoemd.",
            particularites = "De zeer zeldzame roze-paarse variëteit, hexagoniet, dankt haar kleur aan mangaan en wordt vóór analyse soms verward met tanzaniet.",
            inclusions = "Karakteristieke vezelige structuur, vaak verantwoordelijk voor een chatoyant effect bij als cabochon geslepen stenen.",
            lithotherapie = "Tremoliet zou zachtheid en flexibiliteit bevorderen bij veranderingen, in weerklank met zijn vezelige structuur."
        ),
        "oeil-de-taureau" to GemTranslation(
            nom = "Stierenoog",
            descriptionCourte = "Verhit tijgeroog, waarvan de ijzeroxidatie naar diep roodbruin verschuift.",
            descriptionLongue = "Stierenoog wordt verkregen door gecontroleerde verhitting van goudkleurig tijgeroog, een behandeling die de ijzeroxidatie versterkt en de tint van geelbruin naar een diep, uitgesproken roodbruin doet verschuiven, terwijl de karakteristieke zijdeachtige chatoyance van de vezelstructuur behouden blijft.",
            particularites = "De thermische behandeling die deze roodbruine tint oplevert, is gangbaar en algemeen aanvaard in de handel, mits vermeld.",
            lithotherapie = "Stierenoog wordt geassocieerd met kracht, geaardheid en vastberadenheid, in symbolische voortzetting van tijgeroog."
        ),
        "unakite" to GemTranslation(
            nom = "Unakiet",
            descriptionCourte = "Een groen-roze gespikkeld gesteente, mengsel van verweerd graniet.",
            descriptionLongue = "Unakiet is een verweerd granitisch gesteente, samengesteld uit een karakteristiek mengsel van roze veldspaat, groene epidoot en kwarts, wat het een onmiddellijk herkenbaar gespikkeld patroon geeft. Genoemd naar de Unaka Mountains in North Carolina waar het werd beschreven, wordt het vooral geslepen tot cabochons en kralen.",
            particularites = "Als samengesteld gesteente en geen enkelvoudig mineraal variëren de hardheid en brekingsindex licht naargelang de verhouding van elk bestanddeel.",
            lithotherapie = "Unakiet wordt van oudsher geassocieerd met emotioneel evenwicht en geleidelijke genezing na een emotionele beproeving."
        ),
        "oeil-de-sainte-lucie" to GemTranslation(
            nom = "Sint-Luciaoog",
            descriptionCourte = "Het spiraalvormige deksel van een zeeslak, al sinds de oudheid als amulet gedragen.",
            descriptionLongue = "Het Sint-Luciaoog is het kalkachtige deksel, de kleine \"deur\" die de opening van de schelp van bepaalde zeeslakken uit het geslacht Turbo afsluit. Het bruin-crèmekleurige spiraalpatroon, dat aan een oog doet denken, maakte er in veel mediterrane culturen een traditionele beschermende amulet van.",
            particularites = "Het is geen schelp maar het deksel, het kalkstuk dat de opening van de levende schelp afsluit; het laat na de dood van het dier van nature los.",
            lithotherapie = "Al sinds de oudheid als hanger gedragen, wordt deze amulet geacht te beschermen tegen het boze oog en geluk te brengen aan de drager."
        ),
        "jais" to GemTranslation(
            nom = "Git",
            descriptionCourte = "Een dof zwart fossiel steenkool, het symbool van de Victoriaanse rouw.",
            descriptionLongue = "Git is een compacte variëteit van ligniet, hout dat miljoenen jaren onder hoge druk is gefossiliseerd, gepolijst tot een diep, fluweelzacht zwart. De lichtheid en de gemakkelijke bewerkbaarheid maakten er het kenmerkende materiaal van de rouwjuwelen van het Victoriaanse tijdperk van, met name rond Whitby in Engeland.",
            particularites = "Warmt snel op bij contact met de huid en kan door wrijving een elektrostatische lading ontwikkelen, net als barnsteen.",
            lithotherapie = "Git wordt van oudsher geassocieerd met bescherming tegen negatieve energieën en het begeleiden van rouw."
        ),
        "vivianite" to GemTranslation(
            nom = "Vivianiet",
            descriptionCourte = "Een dieppaars-blauw ijzerfosfaat, zo zacht en lichtgevoelig dat het een verzamelaarsmineraal blijft.",
            descriptionLongue = "Vivianiet ontstaat door de verwering van ijzerhoudende mineralen in zuurstofarme milieus — veengebieden, klei, of op het oppervlak van fossiele botten en tanden, waar het bijvoorbeeld sommige Siberische mammoetslagtanden blauwgroen kleurt. Vers opgegraven bijna kleurloos, verdonkert het binnen enkele uren lichtblootstelling tot een diep indigoblauw, soms bijna zwart, door oxidatie van het aanwezige ijzer. De mooiste, langgerekte en goed gevormde kristallen komen tegenwoordig bijna uitsluitend uit de mijn van Anloa in Bolivia.",
            particularites = "Uiterst zacht en gevoelig voor licht en warmte, wordt het vrijwel nooit geslepen voor sieraden: bewaard uit direct licht om de kleur te behouden, blijft het een verzamelaarssteen. De volmaakte splijting levert dunne, bijna buigzame lamellen op.",
            lithotherapie = "In lithotherapie-tradities wordt vivianiet geassocieerd met loslaten en innerlijke transformatie — een traditioneel geloof, zonder vastgestelde wetenschappelijke basis.",
            inclusions = "Het onderscheidende kenmerk van deze soort is geen insluitsel maar een kleurverandering: vers blootgelegde, bijna kleurloze kristallen verdonkeren binnen enkele uren lichtblootstelling tot een diep blauw door oxidatie van het aanwezige ijzer."
        ),
        "grenat-etoile" to GemTranslation(
            nom = "Sterrengranaat",
            descriptionCourte = "Een almandijn met vier of zes lichtstralen, een zeldzaamheid die vrijwel uitsluitend in Idaho wordt gevonden.",
            descriptionLongue = "Sterrengranaat is een almandijn waarbij fijne georiënteerde insluitsels (meestal rutiel) onder puntverlichting een vier- of, zeldzamer, zesstralig asterisme veroorzaken. Hij is in edelsteenkwaliteit slechts op twee plaatsen ter wereld bekend: Idaho in de Verenigde Staten en enkele vindplaatsen in India.",
            particularites = "Idaho is de enige plek ter wereld waar granaten met vierstralig asterisme worden gevonden; de zeldzamere zesstralige sterren komen uit dezelfde vindplaatsen.",
            lithotherapie = "Sterrengranaat wordt geassocieerd met innerlijke kracht en houvast in momenten van onzekerheid."
        ),
        "opale-peruvienne" to GemTranslation(
            nom = "Peruaanse opaal",
            descriptionCourte = "Een ondoorzichtige blauwgroene of roze opaal, zonder kleurenspel, uniek voor Peru.",
            descriptionLongue = "Peruaanse opaal is een gewone, ondoorzichtige opaal, in een blauwgroen dat aan zeewater doet denken of, zeldzamer, in een zacht roze — twee tinten die aan sporen koper te danken zijn. Uitsluitend gewonnen in de Peruaanse Andes, wordt het geslepen als cabochons voor de juwelierskunst.",
            particularites = "Zijn kleur komt van sporen koper, een zeldzaam kleuringsfenomeen bij opalen, die van nature meestal kleurloos zijn in de diepte.",
            lithotherapie = "Peruaanse opaal wordt geassocieerd met emotionele kalmering en communicatie, in resonantie met zijn blauwgroene tint."
        ),
        "opale-commune" to GemTranslation(
            nom = "Gewone opaal",
            descriptionCourte = "De meest voorkomende opaalvariëteit, melkachtig en zonder kleurenspel.",
            descriptionLongue = "Gewone opaal, of melkopaal, vormt het grootste deel van de wereldwijde opaalproductie maar vertoont niet het kleurenspel dat de waarde van edelopaal bepaalt. Wit, doorschijnend of soms getint, wordt het geslepen als cabochons tegen een toegankelijke prijs.",
            particularites = "De afwezigheid van kleurenspel onderscheidt gewone opaal van edelopaal; beide delen echter dezelfde samenstelling.",
            lithotherapie = "Gewone opaal zou zachtheid en dagelijkse kalmering brengen."
        ),
        "opale-noire" to GemTranslation(
            nom = "Zwarte opaal",
            descriptionCourte = "Het spectaculairste kleurenspel, op een donkere ondergrond die het laat opvallen.",
            descriptionLongue = "Zwarte opaal dankt zijn naam aan zijn donkere, grijze tot zwarte ondergrond, waarop het kleurenspel met ongeëvenaarde intensiteit naar voren komt. Vrijwel uitsluitend gewonnen in Lightning Ridge, New South Wales, geldt het als de meest kostbare opaal.",
            particularites = "De donkere ondergrond komt van sporen koolstof en ijzeroxiden tussen de silicabolletjes, een fenomeen eigen aan de vindplaats Lightning Ridge.",
            lithotherapie = "Zwarte opaal wordt geassocieerd met innerlijke transformatie en bescherming in periodes van diepgaande verandering."
        ),
        "opale-boulder" to GemTranslation(
            nom = "Boulderopaal",
            descriptionCourte = "Een dun sluier van opaal op zijn ijzerhoudende zandsteenmatrix, bij het slijpen intact gelaten.",
            descriptionLongue = "Boulderopaal vormt zich in fijne aders binnen een bruin ijzerhoudend gesteente (ironstone) uit Queensland. In plaats van de opaal, die te dun en broos is, van zijn matrix te scheiden, slijpen lapidaristen de steen met behoud van de natuurlijke bruine ondergrond, die het kleurenspel doet uitkomen.",
            particularites = "In tegenstelling tot andere opalen omvat het bewust zijn gastgesteente, wat het schokbestendiger maakt dan een zuivere opaal.",
            lithotherapie = "Boulderopaal wordt geassocieerd met geaardheid en stevigheid, in resonantie met het gesteente dat het draagt."
        ),
        "opale-ethiopie" to GemTranslation(
            nom = "Ethiopische opaal",
            descriptionCourte = "Een opaal met levendig kleurenspel op een honingkleurige ondergrond, maar hydrofaan en dus kwetsbaar voor water.",
            descriptionLongue = "In de jaren 2010 ontdekt in de regio Wollo, heeft de Ethiopische opaal de markt op zijn kop gezet door zijn bijzonder levendige kleurenspel op een doorschijnende honing- tot kleurloze ondergrond. Zijn hydrofane aard — het absorbeert water als een spons — maakt het echter instabiel bij onderdompeling of te grote blootstelling aan vocht.",
            particularites = "Hydrofane aard: kan tot 20% van zijn volume aan water absorberen, kan scheuren bij het drogen, en zijn transparantie kan tijdelijk veranderen bij contact met vocht.",
            inclusions = "Hydrofane (poreuze) aard die water kan absorberen en de transparantie tijdelijk kan wijzigen; interne structuur van silicabolletjes verantwoordelijk voor het kleurenspel.",
            lithotherapie = "Ethiopische opaal wordt, zoals andere edelopalen, geacht emoties en creativiteit te versterken."
        ),
        "marcassite" to GemTranslation(
            nom = "Markasiet",
